ter_flags.contains(&FFF::NoSymlinks),\\r\\n  40:             show_symlinks:    filter_flags.contains(&FFF::ShowSymlinks),\\r\\n  41:             flags:            filter_flags,\\r\\n  42:             sort_field:       SortField::deduce(matches)?,\\r\\n  43:             dot_filter:       DotFilter::deduce(matches)?,\\r\\n  44:             ignore_patterns:  IgnorePatterns::deduce(matches)?,\\r\\n  45:             git_ignore:       GitIgnore::deduce(matches)?,\\r\\n  46:         });\\r\\n  47:     }\\r\\n  48: }\\r\\n  49: \\r\\n  50: impl SortField {\\r\\n  51:     /// Determines which sort field to use based on the `--sort` argument.\\r\\n  52:     /// This argument’s value can be one of several flags, listed above.\\r\\n  53:     /// Returns the default sort field if none is given, or `Err` if the\\r\\n  54:     /// value doesn’t correspond to a sort field we know about.\\r\\n  55:     fn deduce(matches: &MatchedFlags<'_>) -> Result<Self, OptionsError> {\\r\\n  56:         let Some(word) = matches.get(&flags::SORT)? else {\\r\\n  57:             return Ok(Self::default());\\r\\n  58:         };\\r\\n  59: \\r\\n  60:         // Get String because we can’t match an OsStr\\r\\n  61:         let Some(word) = word.to_str() else {\\r\\n  62:             return Err(OptionsError::BadArgument(&flags::SORT, word.into()));\\r\\n  63:         };\\r\\n  64: \\r\\n  65:         let field = match word {\\r\\n  66:             \\\"name\\\" | \\\"filename\\\" => Self::Name(SortCase::AaBbCc),\\r\\n  67:             \\\"Name\\\" | \\\"Filename\\\" => Self::Name(SortCase::ABCabc),\\r\\n  68:             \\\".name\\\" | \\\".filename\\\" => Self::NameMixHidden(SortCase::AaBbCc),\\r\\n  69:             \\\".Name\\\" | \\\".Filename\\\" => Self::NameMixHidden(SortCase::ABCabc),\\r\\n  70:             \\\"size\\\" | \\\"filesize\\\" => Self::Size,\\r\\n  71:             \\\"ext\\\" | \\\"extension\\\" => Self::Extension(SortCase::AaBbCc),\\r\\n  72:             \\\"Ext\\\" | \\\"Extension\\\" => Self::Extension(SortCase::ABCabc),\\r\\n  73: \\r\\n  74:             // “new” sorts oldest at the top and newest at the bottom; “old”\\r\\n  75:             // sorts newest at the top and oldest at the bottom. I think this\\r\\n  76:             // is the right way round to do this: “size” puts the smallest at\\r\\n  77:             // the top and the largest at the bottom, doesn’t it?\\r\\n  78:             \\\"date\\\" | \\\"time\\\" | \\\"mod\\\" | \\\"modified\\\" | \\\"new\\\" | \\\"newest\\\" => Self::ModifiedDate,\\r\\n  79: \\r\\n  80:             // Similarly, “age” means that files with the least age (the\\r\\n  81:             // newest files) get sorted at the top, and files with the most\\r\\n  82:             // age (the oldest) at the bottom.\\r\\n  83:             \\\"age\\\" | \\\"old\\\" | \\\"oldest\\\" => Self::ModifiedAge,\\r\\n  84: \\r\\n  85:             \\\"ch\\\" | \\\"changed\\\" => Self::ChangedDate,\\r\\n  86:             \\\"acc\\\" | \\\"accessed\\\" => Self::AccessedDate,\\r\\n  87:             \\\"cr\\\" | \\\"created\\\" => Self::CreatedDate,\\r\\n  88:             #[cfg(unix)]\\r\\n  89:             \\\"inode\\\" => Self::FileInode,\\r\\n  90:             \\\"type\\\" => Self::FileType,\\r\\n  91:             \\\"none\\\" => Self::Unsorted,\\r\\n  92:             _ => {\\r\\n  93:                 return Err(OptionsError::BadArgument(&flags::SORT, word.into()));\\r\\n  94:             }\\r\\n  95:         };\\r\\n  96: \\r\\n  97:         Ok(field)\\r\\n  98:     }\\r\\n  99: }\\r\\n 100: \\r\\n 101: // I’ve gone back and forth between whether to sort case-sensitively or\\r\\n 102: // insensitively by default. The default string sort ...57 characters truncated...twice or more in strict mode.\\r\\n  27:     Duplicate(Flag, Flag),\\r\\n  28: \\r\\n  29:     /// Two options were given that conflict with one another.\\r\\n  30:     Conflict(&'static Arg, &'static Arg),\\r\\n  31: \\r\\n  32:     /// An option was given that doe