alue{choices}\\\")\",\"\",\"\",\"def parse_arguments(argv: Sequence[str]) -> tuple[list[Occurrence], list[str]]:\",\"    occurrences: list[Occurrence] = []\",\"    paths: list[str] = []\",\"    i = 0\",\"    position = 0\",\"    options_done = False\",\"\",\"    while i < len(argv):\",\"        token = argv[i]\",\"        if options_done or token == \\\"-\\\" or not token.startswith(\\\"-\\\"):\",\"            paths.append(token)\",\"            i += 1\",\"            continue\",\"        if token == \\\"--\\\":\",\"            options_done = True\",\"            i += 1\",\"            continue\",\"\",\"        if token.startswith(\\\"--\\\"):\",\"            body = token[2:]\",\"            name, equal, attached = body.partition(\\\"=\\\")\",\"            spec = LONG_SPECS.get(name)\",\"            if spec is None:\",\"                raise unknown_argument(f\\\"--{name}\\\")\",\"            spelling = f\\\"--{name}\\\"\",\"            value: Optional[str] = None\",\"            if spec.value_kind == \\\"none\\\":\",\"                if equal:\",\"                    raise CliError(f\\\"Flag {spelling} cannot take a value\\\")\",\"            elif spec.value_kind == \\\"required\\\":\",\"                if equal:\",\"                    value = attached\",\"                elif i + 1 < len(argv):\",\"                    i += 1\",\"                    value = argv[i]\",\"                else:\",\"                    raise needs_value(spelling, spec)\",\"            else:\",\"                if equal:\",\"                    value = attached\",\"                elif i + 1 < len(argv) and argv[i + 1] in spec.choices:\",\"                    i += 1\",\"                    value = argv[i]\",\"                else:\",\"                    value = spec.default\",\"            occurrences.append(Occurrence(spec.canonical, value, position, spelling))\",\"            position += 1\",\"            i += 1\",\"            continue\",\"\",\"        cluster = token[1:]\",\"        j = 0\",\"        while j < len(cluster):\",\"            short = cluster[j]\",\"            if short == \\\"=\\\":\",\"                raise unknown_argument(\\\"-=\\\")\",\"            spec = SHORT_SPECS.get(short)\",\"            if spec is None:\",\"                raise unknown_argument(f\\\"-{short}\\\")\",\"            spelling = f\\\"-{short}\\\"\",\"            value = None\",\"            if spec.value_kind == \\\"none\\\":\",\"                occurrences.append(Occurrence(spec.canonical, None, position, spelling))\",\"                position += 1\",\"                j += 1\",\"                continue\",\"\",\"            rest = cluster[j + 1 :]\",\"            if rest.startswith(\\\"=\\\"):\",\"                rest = rest[1:]\",\"            if spec.value_kind == \\\"required\\\":\",\"                if rest:\",\"                    value = rest\",\"                elif i + 1 < len(argv):\",\"                    i += 1\",\"                    value = argv[i]\",\"                else:\",\"                    raise needs_value(spelling, spec)\",\"            else:\",\"                if rest:\",\"                    if rest not in spec.choices:\",\"                        raise CliError(f\\\"Flag {spelling} cannot take a value\\\")\",\"                    value = rest\",\"                elif i + 1 < len(argv) and argv[i + 1] in spec.choices:\",\"                    i += 1\",\"                    value = argv[i]\",\"                else:\",\"                    value = spec.default\",\"            occurrences.append(Occurrence(spec.canonical, value, position, spelling))\",\"            position += 1\",\"            break\",\"        i += 1\",\"\",\"    return occurrences, paths\",\"\",\"\",\"@dataclass\",\"class Config:\",\"    occurrences: list[Occurrence]\",\"    paths: list[str]\",\"    mode: str = \\\"lines\\\"\",\"    table: bool = False\",\"    tree: bool = False\",\"    width: Optional[int] = None\",\"    across: bool = False\",\"    recurse: bool = False\",\"    level: Optional[int] = None\",\"    all_count: int = 0\",\"    show_hidden: bool = False\",\"    show_dots: bool = False\",\"    sort_field: str = \\\"name\\\"\",\"    sort_upper_first: bool = False\",\"    reverse: bool = False\",\"    dirs_first: bool = False\",\"    dirs_last: bool = False\",\"    only_dirs: bool = False\",\"    only_files: bool = False\",\"    no_symlinks: bool = False\",\"    show_symlinks: bool = False\",\"    ignore_patterns: list[str] = field(default_factory=list)\",\"    treat_dirs: bool = False\",\"    follow_symlinks: bool = False\",\"    dereference: bool = False\",\"    classify: str = \\\"never\\\"\",\"    no_quotes: bool = False\",\"    absolute: str = \\\"off\\\"\",\"    header: bool = False\",\"    permissions: bool = True\",\"    filesize: bool = True\",\"    file_flags: bool = False\",\"    size_format: str = \\\"decimal\\\"\",\"    time_fields: list[str] = field(default_factory=lambda: [\\\"modified\\\"])\",\"    time_style: str = \\\"default\\\"\",\"\",\"    def has(self, name: str) -> bool:\",\"        return any(o.canonical == name for o in self.occurrences)\",\"\",\"    def count(self, name: str) -> int:\",\"        return sum(o.canonical == name for o in self.occurrences)\",\"\",\"    def last(self, *names: str) -> Optional[Occurrence]:\",\"        choices = [o for o in self.occurrences if o.canonical in names]\",\"        return max(choices, key=lambda o: o.position) if choices else None\",\"\",\"\",\"def parse_nonnegative(value: str, source: str) -> int:\",\"    if not value or not value.isascii() or not value.isdigit():\",\"        raise CliError(\",\"            f'Value \\\"{value}\\\" not valid for option {option_label(source)}: '\",\"            \\\"invalid digit found in string\\\"\",\"        )\",\"    return int(value)\",\"\",\"\",\"def make_config(occurrences: list[Occurrence], paths: list[str]) -> Config:\",\"    cfg = Config(occurrences, paths)\",\"\",\"    width_occ = cfg.last(\\\"width\\\")\",\"    if width_occ is not None:\",\"        cfg.width = parse_nonnegative(width_occ.value or \\\"\\\", \\\"width\\\")\",\"    elif os.environ.get(\\\"COLUMNS\\\"):\",\"        value = os.environ[\\\"COLUMNS\\\"]\",\"        if not value.isdigit():\",\"            raise CliError(\",\"                f'Value \\\"{value}\\\" not valid for environment variable COLUMNS: '\",\"                \\\"invalid digit found in string\\\"\",\"            )\",\"        cfg.width = int(value)\",\"    elif sys.stdout.isatty():\",\"        cfg.width = shutil.get_terminal_size((80, 24)).columns\",\"\",\"    display = cfg.last(\\\"long\\\", \\\"oneline\\\", \\\"grid\\\", \\\"tree\\\")\",\"    has_long = cfg.has(\\\"long\\\")\",\"    if display is None:\",\"        cfg.mode = \\\"grid\\\" if cfg.width is not None else \\\"lines\\\"\",\"    elif display.canonical == \\\"long\\\" or (\",\"        display.canonical in (\\\"tree\\\", \\\"grid\\\") and has_long\",\"    ):\",\"        last_structure = cfg.last(\\\"grid\\\", \\\"tree\\\")\",\"        cfg.mode = (\",\"            \\\"grid-details\\\"\",\"            if last_structure is not None and last_structure.canonical == \\\"grid\\\"\",\"            else \\\"details\\\"\",\"        )\",\"    elif display.canonical == \\\"tree\\\":\",\"        cfg.mode = \\\"details\\\"\",\"        cfg.tree = True\",\"    elif display.canonical == \\\"oneline\\\":\",\"        cfg.mode = \\\"lines\\\"\",\"    else:\",\"        cfg.mode = \\\"grid\\\"\",\"\",\"    if cfg.has(\\\"tree\\\") and cfg.mode == \\\"details\\\":\",\"        last_structure = cfg.last(\\\"tree\\\", \\\"grid\\\")\",\"        cfg.tree = last_structure is not None and last_structure.canonical == \\\"tree\\\"\",\"    cfg.table = has_long and cfg.mode in (\\\"details\\\", \\\"grid-details\\\")\",\"    cfg.across = cfg.has(\\\"across\\\")\",\"    cfg.recurse = cfg.has(\\\"recurse\\\") or cfg.tree\",\"\",\"    level_occ = cfg.last(\\\"level\\\")\",\"    if level_occ is not None and cfg.recurse:\",\"        cfg.level = parse_nonnegative(level_occ.value or \\\"\\\", \\\"level\\\")\",\"        if cfg.level == 0:\",\"            cfg.level = None\",\"\",\"    cfg.all_count = cfg.count(\\\"all\\\")\",\"    cfg.show_hidden = cfg.all_count > 0 or cfg.has(\\\"almost-all\\\")\",\"    cfg.show_dots = cfg.all_count >= 2\",\"    if cfg.has(\\\"tree\\\") and cfg.show_dots:\",\"        raise CliError(\\\"Option --tree is useless given --all --all\\\")\",\"\",\"    sort_occ = cfg.last(\\\"sort\\\")\",\"    sort_value = sort_occ.value if sort_occ else \\\"name\\\"\",\"    if sort_value == \\\"inode\\\" and os.name == \\\"nt\\\":\",\"        sort_spec = None\",\"    else:\",\"        sort_spec = SORT_ALIASES.get(sort_value or \\\"\\\")\",\"    if sort_spec is None:\",\"        choices = \\\", \\\".join(SORT_CHOICES)\",\"        raise CliError(\",\"            f'Option --sort (-s) has no \\\"{sort_value}\\\" setting (choices: {choices})'\",\"        )\",\"    cfg.sort_field, cfg.sort_upper_first = sort_spec\",\"\",\"    cfg.reverse = cfg.has(\\\"reverse\\\")\",\"    cfg.dirs_first = cfg.has(\\\"dirs-first\\\")\",\"    cfg.dirs_last = cfg.has(\\\"dirs-last\\\")\",\"    cfg.only_dirs = cfg.has(\\\"only-dirs\\\")\",\"    cfg.only_files = cfg.has(\\\"only-files\\\")\",\"    cfg.no_symlinks = cfg.has(\\\"no-symlinks\\\")\",\"    cfg.show_symlinks = cfg.has(\\\"show-symlinks\\\")\",\"    cfg.treat_dirs = cfg.has(\\\"treat-dirs-as-files\\\") or cfg.has(\\\"list-dirs\\\")\",\"    cfg.follow_symlinks = cfg.has(\\\"follow-symlinks\\\")\",\"    cfg.dereference = cfg.has(\\\"dereference\\\")\",\"\",\"    for occurrence in occurrences:\",\"        if occurrence.canonical == \\\"ignore-glob\\\" and occurrence.value is not None:\",\"            cfg.ignore_patterns.extend(occurrence.value.split(\\\"|\\\"))\",\"\",\"    classify = cfg.last(\\\"classify\\\")\",\"    if classify:\",\"        value = classify.value or \\\"auto\\\"\",\"        if value not in (\\\"always\\\", \\\"auto\\\", \\\"automatic\\\", \\\"never\\\"):\",\"            raise CliError(f'Option --classify (-F) has no \\\"{value}\\\" setting')\",\"        cfg.classify = \\\"always\\\" if value == \\\"always\\\" else \\\"never\\\"\",\"\",\"    absolute = cfg.last(\\\"absolute\\\")\",\"    if absolute:\",\"        value = absolute.value or \\\"on\\\"\",\"        if value not in (\\\"on\\\", \\\"yes\\\", \\\"follow\\\", \\\"off\\\", \\\"no\\\"):\",\"            raise CliError(f'Option --absolute has no \\\"{value}\\\" setting')\",\"        cfg.absolute = \\\"off\\\" if value in (\\\"off\\\", \\\"no\\\") else value\",\"\",\"    cfg.no_quotes = cfg.has(\\\"no-quotes\\\")\",\"    cfg.header = cfg.has(\\\"header\\\") and cfg.table\",\"    cfg.permissions = not cfg.has(\\\"no-permissions\\\")\",\"    cfg.filesize = not cfg.has(\\\"no-filesize\\\")\",\"    cfg.file_flags = cfg.has(\\\"flags\\\")\",\"\",\"    size_occ = cfg.last(\\\"binary\\\", \\\"bytes\\\")\",\"    if size_occ and size_occ.canonical == \\\"binary\\\":\",\"        cfg.size_format = \\\"binary\\\"\",\"    elif size_occ and size_occ.canonical == \\\"bytes\\\":\",\"        cfg.size_format = \\\"bytes\\\"\",\"\",\"    explicit_times: list[str] = []\",\"    time_value = cfg.last(\\\"time\\\")\",\"    if time_value:\",\"        if time_value.value not in (\\\"modified\\\", \\\"changed\\\", \\\"accessed\\\", \\\"created\\\"):\",\"            choices = \\\"modified, changed, accessed, created\\\"\",\"            raise CliError(\",\"                f'Option --time (-t) has no \\\"{time_value.value}\\\" setting '\",\"                f\\\"(choices: {choices})\\\"\",\"            )\",\"        explicit_times.append(time_value.value or \\\"modified\\\")\",\"    for name in (\\\"modified\\\", \\\"changed\\\", \\\"created\\\", \\\"accessed\\\"):\",\"        if cfg.has(name) and name not in explicit_times:\",\"            explicit_times.append(name)\",\"    if explicit_times:\",\"        cfg.time_fields = [\",\"            name\",\"            for name in (\\\"modified\\\", \\\"changed\\\", \\\"created\\\", \\\"accessed\\\")\",\"            if name in explicit_times\",\"        ]\",\"    if cfg.has(\\\"no-time\\\"):\",\"        cfg.time_fields = []\",\"\",\"    style_occ = cfg.last(\\\"time-style\\\")\",\"    if style_occ and cfg.table:\",\"        value = style_occ.value or \\\"\\\"\",\"        if value not in (\\\"default\\\", \\\"iso\\\", \\\"long-iso\\\", \\\"full-iso\\\", \\\"relative\\\") and not value.startswith(\\\"+\\\"):\",\"            choices = \\\"default, long-iso, full-iso, iso, relative\\\"\",\"            raise CliError(\",\"                f'Option --time-style has no \\\"{value}\\\" setting (choices: {choices})'\",\"            )\",\"        cfg.time_style = value\",\"    elif cfg.table and os.environ.get(\\\"TIME_STYLE\\\"):\",\"        cfg.time_style = os.environ[\\\"TIME_STYLE\\\"]\",\"\",\"    return cfg\",\"\",\"\",\"_MISSING = object()\",\"\",\"\",\"@dataclass\",\"class Entry:\",\"    path: str\",\"    name: str\",\"    parent_dir: Optional[str] = None\",\"    synthetic: bool = False\",\"    dereference: bool = False\",\"    _lstat_value: object = field(default=_MISSING, repr=False)\",\"    _stat_value: object = field(default=_MISSING, repr=False)\",\"\",\"    def lstat(self):\",\"        if self._lstat_value is _MISSING:\",\"            self._lstat_value = os.lstat(self.path)\",\"        return self._lstat_value\",\"\",\"    def metadata(self):\",\"        if not self.dereference:\",\"            return self.lstat()\",\"        if self._stat_value is _MISSING:\",\"            self._stat_value = os.stat(self.path)\",\"        return self._stat_value\",\"\",\"    def is_link(self) -> bool:\",\"        try:\",\"            return os.path.islink(self.path) or stat.S_ISLNK(self.lstat().st_mode)\",\"        except OSError:\",\"            return False\",\"\",\"    def is_directory(self) -> bool:\",\"        if self.is_link() and not self.dereference:\",\"            return False\",\"        try:\",\"            return stat.S_ISDIR(self.metadata().st_mode)\",\"        except OSError:\",\"            return False\",\"\",\"    def points_to_directory(self) -> bool:\",\"        try:\",\"            return os.path.isdir(self.path)\",\"        except OSError:\",\"            return False\",\"\",\"    def is_file(self) -> bool:\",\"        if self.is_link() and not self.dereference:\",\"            return False\",\"        try:\",\"            return stat.S_ISREG(self.metadata().st_mode)\",\"        except OSError:\",\"            return False\",\"\",\"    def attributes(self) -> int:\",\"        try:\",\"            return int(getattr(self.metadata(), \\\"st_file_attributes\\\", 0))\",\"        except OSError:\",\"            return 0\",\"\",\"    def size(self) -> Optional[int]:\",\"        if self.is_directory():\",\"            return None\",\"        try:\",\"            return int(self.metadata().st_size)\",\"        except OSError:\",\"            return 0\",\"\",\"    def time_ns(self, kind: str) -> Optional[int]:\",\"        try:\",\"            metadata = self.metadata()\",\"        except OSError:\",\"            return None\",\"        if kind == \\\"modified\\\":\",\"            return int(metadata.st_mtime_ns)\",\"        if kind == \\\"accessed\\\":\",\"            return int(metadata.st_atime_ns)\",\"        if kind == \\\"created\\\":\",\"            return int(metadata.st_ctime_ns)\",\"        return None\",\"\",\"    def type_rank(self) -> int:\",\"        if self.is_directory():\",\"            return 0\",\"        if self.is_file():\",\"            return 1\",\"        if self.is_link():\",\"            return 2\",\"        return 7\",\"\",\"\",\"def path_name(path: str) -> str:\",\"    trimmed = path.rstrip(\\\"/\\\\\\\\\\\")\",\"    if not trimmed:\",\"        return path\",\"    name = os.path.basename(trimmed)\",\"    return name if name else trimmed\",\"\",\"\",\"def make_entry(path: str, parent_dir: Optional[str] = None, name: Optional[str] = None, *, cfg: Config) -> Entry:\",\"    return Entry(\",\"        path=path,\",\"        name=path_name(path) if name is None else name,\",\"        parent_dir=parent_dir,\",\"        dereference=cfg.dereference,\",\"    )\",\"\",\"\",\"def display_width(text: str) -> int:\",\"    width = 0\",\"    for char in text:\",\"        if unicodedata.combining(char):\",\"            continue\",\"        width += 2 if unicodedata.east_asian_width(char) in (\\\"W\\\", \\\"F\\\") else 1\",\"    return width\",\"\",\"\",\"def escaped(text: str) -> str:\",\"    replacements = {\",\"        \\\"\\\\n\\\": r\\\"\\\\n\\\",\",\"        \\\"\\\\r\\\": r\\\"\\\\r\\\",\",\"        \\\"\\\\t\\\": r\\\"\\\\t\\\",\",\"        \\\"\\\\x1b\\\": r\\\"\\\\e\\\",\",\"    }\",\"    bits = []\",\"    for char in text:\",\"        if char in replacements:\",\"            bits.append(replacements[char])\",\"        elif ord(char) < 32 or ord(char) == 127:\",\"            bits.append(f\\\"\\\\\\\\x{ord(char):02x}\\\")\",\"        else:\",\"            bits.append(char)\",\"    return \\\"\\\".join(bits)\",\"\",\"\",\"def quote(text: str, no_quotes: bool = False) -> str:\",\"    text = escaped(text)\",\"    if no_quotes or not any(char.isspace() for char in text):\",\"        return text\",\"    return \\\"'\\\" + text.replace(\\\"'\\\", \\\"\\\\\\\\'\\\") + \\\"'\\\"\",\"\",\"\",\"def explicit_display_path(entry: Entry, cfg: Config) -> str:\",\"    if cfg.absolute != \\\"off\\\":\",\"        result = os.path.realpath(entry.path) if cfg.absolute == \\\"follow\\\" else os.path.abspath(entry.path)\",\"        return quote(result, cfg.no_quotes)\",\"    if entry.parent_dir is not None:\",\"        return quote(entry.name, cfg.no_quotes)\",\"    parent = os.path.dirname(entry.path)\",\"    if not parent:\",\"        return quote(entry.name, cfg.no_quotes)\",\"    return quote(parent, cfg.no_quotes) + os.sep + quote(entry.name, cfg.no_quotes)\",\"\",\"\",\"def link_target(entry: Entry) -> Optional[str]:\",\"    if not entry.is_link():\",\"        return None\",\"    try:\",\"        return os.readlink(entry.path)\",\"    except OSError:\",\"        return None\",\"\",\"\",\"def render_name(entry: Entry, cfg: Config, *, show_link: bool) -> str:\",\"    name = explicit_display_path(entry, cfg)\",\"    target = link_target(entry) if show_link else None\",\"    if target is not None:\",\"        target_text = quote(target, False)\",\"        if cfg.classify == \\\"always\\\":\",\"            target_path = target if os.path.isabs(target) else os.path.join(os.path.dirname(entry.path), target)\",\"            if os.path.isdir(target_path):\",\"                target_text += \\\"/\\\"\",\"        return f\\\"{name} -> {target_text}\\\"\",\"    if cfg.classify == \\\"always\\\":\",\"        if entry.is_directory():\",\"            name += \\\"/\\\"\",\"        elif entry.is_link():\",\"            name += \\\"@\\\"\",\"    return name\",\"\",\"\",\"def natural_key(text: str, upper_first: bool = False):\",\"    parts = re.split(r\\\"(\\\\d+)\\\", text)\",\"    key = []\",\"    for part in parts:\",\"        if part.isdigit():\",\"            key.append((0, int(part), len(part)))\",\"        else:\",\"            key.append((1, part if upper_first else part.casefold()))\",\"    return tuple(key)\",\"\",\"\",\"def extension_of(name: str) -> Optional[str]:\",\"    position = name.rfind(\\\".\\\")\",\"    return None if position < 0 else name[position + 1 :].lower()\",\"\",\"\",\"def entry_sort_key(entry: Entry, cfg: Config):\",\"    field_name = cfg.sort_field\",\"    if field_name == \\\"none\\\":\",\"        return 0\",\"    if field_name in (\\\"name\\\", \\\"hidden-name\\\"):\",\"        name = entry.name\",\"        if field_name == \\\"hidden-name\\\" and name.startswith(\\\".\\\"):\",\"            name = name[1:]\",\"        return natural_key(name, cfg.sort_upper_first)\",\"    if field_name == \\\"extension\\\":\",\"        extension = extension_of(entry.name)\",\"        if extension is None:\",\"            return (0, (), natural_key(entry.name, cfg.sort_upper_first))\",\"        return (\",\"            1,\",\"            natural_key(extension, cfg.sort_upper_first),\",\"            natural_key(entry.name, cfg.sort_upper_first),\",\"        )\",\"    if field_name == \\\"size\\\":\",\"        size = entry.size()\",\"        return (-1 if size is None else size)\",\"    if field_name == \\\"type\\\":\",\"        return (entry.type_rank(), natural_key(entry.name, False))\",\"    if field_name == \\\"age\\\":\",\"        return -(entry.time_ns(\\\"modified\\\") or 0)\",\"    if field_name in (\\\"modified\\\", \\\"accessed\\\", \\\"created\\\", \\\"changed\\\"):\",\"        return entry.time_ns(field_name) or 0\",\"    return natural_key(entry.name, False)\",\"\",\"\",\"def sort_entries(entries: list[Entry], cfg: Config) -> list[Entry]:\",\"    if cfg.sort_field != \\\"none\\\":\",\"        entries = sorted(entries, key=lambda item: entry_sort_key(item, cfg))\",\"    if cfg.reverse:\",\"        entries.reverse()\",\"    if cfg.dirs_first:\",\"        entries = sorted(entries, key=lambda item: not item.points_to_directory())\",\"    elif cfg.dirs_last:\",\"        entries = sorted(entries, key=lambda item: item.points_to_directory())\",\"    return entries\",\"\",\"\",\"def ignored(name: str, cfg: Config) -> bool:\",\"    return any(fnmatch.fnmatchcase(name, pattern) for pattern in cfg.ignore_patterns)\",\"\",\"\",\"def hidden_entry(entry: Entry) -> bool:\",\"    if entry.name.startswith((\\\".\\\", \\\"_\\\")):\",\"        return True\",\"    return bool(entry.attributes() & FILE_ATTRIBUTE_HIDDEN)\",\"\",\"\",\"def child_passes(entry: Entry, cfg: Config, *, recursing: bool) -> bool:\",\"    if ignored(entry.name, cfg):\",\"        return False\",\"    only_dirs = cfg.only_dirs\",\"    only_files = cfg.only_files\",\"    no_links = cfg.no_symlinks\",\"    show_links = cfg.show_symlinks\",\"    if only_dirs and not only_files:\",\"        if show_links:\",\"            return entry.is_directory() or entry.points_to_directory()\",\"        return entry.is_directory()\",\"    if only_files and not only_dirs:\",\"        if recursing:\",\"            return True\",\"        if show_links:\",\"            return entry.is_file() or (entry.is_link() and not entry.points_to_directory())\",\"        return entry.is_file()\",\"    if no_links and not show_links:\",\"        return not entry.is_link()\",\"    return True\",\"\",\"\",\"def scan_directory(path: str, cfg: Config, *, recursing: bool) -> tuple[list[Entry], Optional[OSError]]:\",\"    entries: list[Entry] = []\",\"    if cfg.show_dots:\",\"        entries.append(Entry(path, \\\".\\\", path, True, cfg.dereference))\",\"        entries.append(Entry(os.path.join(path, \\\"..\\\"), \\\"..\\\", path, True, cfg.dereference))\",\"    try:\",\"        with os.scandir(path) as iterator:\",\"            for item in iterator:\",\"                entry = make_entry(item.path, path, item.name, cfg=cfg)\",\"                if not cfg.show_hidden and hidden_entry(entry):\",\"                    continue\",\"                if child_passes(entry, cfg, recursing=recursing):\",\"                    entries.append(entry)\",\"    except OSError as error:\",\"        return [], error\",\"    return sort_entries(entries, cfg), None\",\"\",\"\",\"def grid_lines(cells: Sequence[str], width: int, across: bool, gap: int = 2) -> list[str]:\",\"    if not cells:\",\"        return []\",\"    count = len(cells)\",\"    chosen_rows = count\",\"    chosen_cols = 1\",\"    chosen_widths = [max(display_width(cell) for cell in cells)]\",\"\",\"    for rows in range(1, count + 1):\",\"        cols = math.ceil(count / rows)\",\"        widths = [0] * cols\",\"        for index, cell in enumerate(cells):\",\"            if across:\",\"                col = index % cols\",\"            else:\",\"                col = index // rows\",\"            widths[col] = max(widths[col], display_width(cell))\",\"        total = sum(widths) + gap * (cols - 1)\",\"        if total <= width or cols == 1:\",\"            chosen_rows, chosen_cols, chosen_widths = rows, cols, widths\",\"            break\",\"\",\"    output: list[str] = []\",\"    for row in range(chosen_rows):\",\"        row_cells: list[tuple[int, str]] = []\",\"        for col in range(chosen_cols):\",\"            index = row * chosen_cols + col if across else col * chosen_rows + row\",\"            if index < count:\",\"                row_cells.append((col, cells[index]))\",\"        if not row_cells:\",\"            continue\",\"        bits: list[str] = []\",\"        for cell_index, (col, cell) in enumerate(row_cells):\",\"            bits.append(cell)\",\"            if cell_index < len(row_cells) - 1:\",\"                padding = chosen_widths[col] - display_width(cell) + gap\",\"                bits.append(\\\" \\\" * padding)\",\"        output.append(\\\"\\\".join(bits))\",\"    return output\",\"\",\"\",\"def windows_mode(entry: Entry) -> str:\",\"    attrs = entry.attributes()\",\"    if entry.is_link():\",\"        kind = \\\"l\\\"\",\"    elif entry.is_directory():\",\"        kind = \\\"d\\\"\",\"    else:\",\"        kind = \\\"-\\\"\",\"    return \\\"\\\".join(\",\"        (\",\"            kind,\",\"            \\\"a\\\" if attrs & FILE_ATTRIBUTE_ARCHIVE else \\\"-\\\",\",\"            \\\"r\\\" if attrs & FILE_ATTRIBUTE_READONLY else \\\"-\\\",\",\"            \\\"h\\\" if attrs & FILE_ATTRIBUTE_HIDDEN else \\\"-\\\",\",\"            \\\"s\\\" if attrs & FILE_ATTRIBUTE_SYSTEM else \\\"-\\\",\",\"        )\",\"    )\",\"\",\"\",\"def file_flags(entry: Entry) -> str:\",\"    attrs = entry.attributes()\",\"    ordered = (\",\"        (FILE_ATTRIBUTE_READONLY, \\\"readonly\\\"),\",\"        (FILE_ATTRIBUTE_HIDDEN, \\\"hidden\\\"),\",\"        (FILE_ATTRIBUTE_SYSTEM, \\\"system\\\"),\",\"        (FILE_ATTRIBUTE_ARCHIVE, \\\"archive\\\"),\",\"        (FILE_ATTRIBUTE_TEMPORARY, \\\"temporary\\\"),\",\"        (FILE_ATTRIBUTE_COMPRESSED, \\\"compressed\\\"),\",\"        (FILE_ATTRIBUTE_OFFLINE, \\\"offline\\\"),\",\"        (FILE_ATTRIBUTE_NOT_CONTENT_INDEXED, \\\"not indexed\\\"),\",\"        (FILE_ATTRIBUTE_ENCRYPTED, \\\"encrypted\\\"),\",\"        (FILE_ATTRIBUTE_NO_SCRUB_DATA, \\\"no scrub\\\"),\",\"        (FILE_ATTRIBUTE_UNPINNED, \\\"unpinned\\\"),\",\"        (FILE_ATTRIBUTE_PINNED, \\\"pinned\\\"),\",\"        (FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS, \\\"recall on data access\\\"),\",\"    )\",\"    names = [name for flag_value, name in ordered if attrs & flag_value]\",\"    return \\\"-\\\" if not names else \\\"-\\\".join(names)\",\"\",\"\",\"def formatted_size(entry: Entry, mode: str) -> str:\",\"    size = entry.size()\",\"    if size is None:\",\"        return \\\"-\\\"\",\"    if mode == \\\"bytes\\\":\",\"        return f\\\"{size:,}\\\"\",\"    base = 1024 if mode == \\\"binary\\\" else 1000\",\"    symbols = (\\\"\\\", \\\"Ki\\\", \\\"Mi\\\", \\\"Gi\\\", \\\"Ti\\\", \\\"Pi\\\", \\\"Ei\\\") if mode == \\\"binary\\\" else (\\\"\\\", \\\"k\\\", \\\"M\\\", \\\"G\\\", \\\"T\\\", \\\"P\\\", \\\"E\\\")\",\"    if size < base:\",\"        return f\\\"{size:,}\\\"\",\"    exponent = min(int(math.log(size, base)), len(symbols) - 1)\",\"    number = size / (base**exponent)\",\"    rendered = f\\\"{number:.1f}\\\" if number < 10 else f\\\"{math.floor(number + 0.5):,}\\\"\",\"    return rendered + symbols[exponent]\",\"\",\"\",\"def fixed_local_datetime(timestamp_ns: int) -> tuple[dt.datetime, dt.timedelta]:\",\"    timestamp = timestamp_ns / 1_000_000_000\",\"    utc = dt.datetime.fromtimestamp(timestamp, dt.timezone.utc).replace(tzinfo=None)\",\"    offset = dt.datetime.now().astimezone().utcoffset() or dt.timedelta(0)\",\"    return utc + offset, offset\",\"\",\"\",\"def relative_time(value: dt.datetime) -> str:\",\"    now = dt.datetime.now()\",\"    seconds = max(0, int((now - value).total_seconds()))\",\"    ranges = (\",\"        (365 * 86400, \\\"year\\\"),\",\"        (30 * 86400, \\\"month\\\"),\",\"        (7 * 86400, \\\"week\\\"),\",\"        (86400, \\\"day\\\"),\",\"        (3600, \\\"hour\\\"),\",\"        (60, \\\"minute\\\"),\",\"    )\",\"    for divisor, label in ranges:\",\"        if seconds >= divisor:\",\"            amount = max(1, math.floor(seconds / divisor + 0.5))\",\"            return f\\\"{amount} {label}{'' if amount == 1 else 's'}\\\"\",\"    return \\\"now\\\"\",\"\",\"\",\"def chrono_custom(value: dt.datetime, pattern: str) -> str:\",\"    pattern = pattern.replace(\\\"%_d\\\", \\\"{EZA_DAY}\\\").replace(\\\"%f\\\", \\\"{EZA_NANO}\\\")\",\"    output = value.strftime(pattern)\",\"    output = output.replace(\\\"{EZA_DAY}\\\", f\\\"{value.day:2d}\\\")\",\"    output = output.replace(\\\"{EZA_NANO}\\\", f\\\"{value.microsecond * 1000:09d}\\\")\",\"    return output\",\"\",\"\",\"def formatted_time(entry: Entry, kind: str, style: str) -> str:\",\"    timestamp_ns = entry.time_ns(kind)\",\"    if timestamp_ns is None:\",\"        return \\\"-\\\"\",\"    value, offset = fixed_local_datetime(timestamp_ns)\",\"    current_year = dt.datetime.now().year\",\"    if style == \\\"default\\\":\",\"        if value.year == current_year:\",\"            return f\\\"{value.day:2d} {value.strftime('%b')} {value:%H:%M}\\\"\",\"        return f\\\"{value.day:2d} {value.strftime('%b')}  {value:%Y}\\\"\",\"    if style == \\\"iso\\\":\",\"        return value.strftime(\\\"%m-%d %H:%M\\\" if value.year == current_year else \\\"%Y-%m-%d\\\")\",\"    if style == \\\"long-iso\\\":\",\"        return value.strftime(\\\"%Y-%m-%d %H:%M\\\")\",\"    if style == \\\"full-iso\\\":\",\"        total_minutes = int(offset.total_seconds() // 60)\",\"        sign = \\\"+\\\" if total_minutes >= 0 else \\\"-\\\"\",\"        total_minutes = abs(total_minutes)\",\"        zone = f\\\"{sign}{total_minutes // 60:02d}{total_minutes % 60:02d}\\\"\",\"        nanos = timestamp_ns % 1_000_000_000\",\"        return value.strftime(\\\"%Y-%m-%d %H:%M:%S\\\") + f\\\".{nanos:09d} {zone}\\\"\",\"    if style == \\\"relative\\\":\",\"        return relative_time(value)\",\"    if style.startswith(\\\"+\\\"):\",\"        formats = style[1:].split(\\\"\\\\n\\\")\",\"        pattern = formats[1] if len(formats) > 1 and value.year == current_year else formats[0]\",\"        return chrono_custom(value, pattern)\",\"    return formatted_time(entry, kind, \\\"default\\\")\",\"\",\"\",\"@dataclass(frozen=True)\",\"class Column:\",\"    key: str\",\"    header: str\",\"    alignment: str\",\"\",\"\",\"def columns_for(cfg: Config) -> list[Column]:\",\"    columns: list[Column] = []\",\"    if cfg.permissions:\",\"        columns.append(Column(\\\"mode\\\", \\\"Mode\\\", \\\"left\\\"))\",\"    if cfg.filesize:\",\"        columns.append(Column(\\\"size\\\", \\\"Size\\\", \\\"right\\\"))\",\"    if cfg.file_flags:\",\"        columns.append(Column(\\\"flags\\\", \\\"Flags\\\", \\\"left\\\"))\",\"    for kind in cfg.time_fields:\",\"        columns.append(Column(f\\\"time:{kind}\\\", f\\\"Date {kind.capitalize()}\\\", \\\"right\\\"))\",\"    return columns\",\"\",\"\",\"def column_value(entry: Entry, column: Column, cfg: Config) -> str:\",\"    if column.key == \\\"mode\\\":\",\"        return windows_mode(entry)\",\"    if column.key == \\\"size\\\":\",\"        return formatted_size(entry, cfg.size_format)\",\"    if column.key == \\\"flags\\\":\",\"        return file_flags(entry)\",\"    if column.key.startswith(\\\"time:\\\"):\",\"        return formatted_time(entry, column.key.split(\\\":\\\", 1)[1], cfg.time_style)\",\"    return \\\"-\\\"\",\"\",\"\",\"@dataclass(frozen=True)\",\"class TreeRow:\",\"    entry: Entry\",\"    prefix: str\",\"\",\"\",\"def prepare_table(rows: Sequence[TreeRow], cfg: Config):\",\"    columns = columns_for(cfg)\",\"    values = [[column_value(row.entry, column, cfg) for column in columns] for row in rows]\",\"    widths = [0] * len(columns)\",\"    for index, column in enumerate(columns):\",\"        if cfg.header:\",\"            widths[index] = display_width(column.header)\",\"        for row_values in values:\",\"            widths[index] = max(widths[index], display_width(row_values[index]))\",\"    return columns, values, widths\",\"\",\"\",\"def render_metadata(values: Sequence[str], columns: Sequence[Column], widths: Sequence[int]) -> str:\",\"    bits: list[str] = []\",\"    for value, column, width in zip(values, columns, widths):\",\"        padding = width - display_width(value)\",\"        if column.alignment == \\\"right\\\":\",\"            bits.append(\\\" \\\" * padding + value)\",\"        else:\",\"            bits.append(value + \\\" \\\" * padding)\",\"        bits.append(\\\" \\\")\",\"    return \\\"\\\".join(bits)\",\"\",\"\",\"def render_details(rows: Sequence[TreeRow], cfg: Config) -> list[str]:\",\"    columns, values, widths = prepare_table(rows, cfg)\",\"    output: list[str] = []\",\"    if cfg.header:\",\"        header_values = [column.header for column in columns]\",\"        output.append(render_metadata(header_values, columns, widths) + \\\"Name\\\")\",\"    for row, row_values in zip(rows, values):\",\"        metadata = render_metadata(row_values, columns, widths)\",\"        output.append(metadata + row.prefix + render_name(row.entry, cfg, show_link=True))\",\"    return output\",\"\",\"\",\"def render_entries(entries: list[Entry], cfg: Config, parent: Optional[str] = None) -> list[str]:\",\"    entries = sort_entries(entries, cfg)\",\"    if cfg.mode == \\\"lines\\\":\",\"        return [render_name(entry, cfg, show_link=True) for entry in entries]\",\"    if cfg.mode == \\\"grid\\\":\",\"        width = cfg.width if cfg.width is not None else 80\",\"        cells = [render_name(entry, cfg, show_link=False) for entry in entries]\",\"        return grid_lines(cells, width, cfg.across)\",\"    rows = [TreeRow(entry, \\\"\\\") for entry in entries]\",\"    if cfg.mode == \\\"grid-details\\\" and cfg.width is not None:\",\"        columns, values, widths = prepare_table(rows, cfg)\",\"        cells = []\",\"        for row, row_values in zip(rows, values):\",\"            details = render_metadata(row_values, columns, widths)\",\"            cells.append(details + \\\" \\\" + render_name(row.entry, cfg, show_link=False))\",\"        threshold = os.environ.get(\\\"EZA_GRID_ROWS\\\") or os.environ.get(\\\"EXA_GRID_ROWS\\\")\",\"        lines = grid_lines(cells, cfg.width, False, 4)\",\"        if threshold and threshold.isdigit() and len(lines) < int(threshold):\",\"            return render_details(rows, cfg)\",\"        if cfg.header and columns:\",\"            combined = render_metadata([column.header for column in columns], columns, widths) + \\\"Name\\\"\",\"            return [combined] + lines\",\"        return lines\",\"    return render_details(rows, cfg)\",\"\",\"\",\"def tree_prefix(ancestors_last: Sequence[bool], last: bool) -> str:\",\"    return \\\"\\\".join(\\\"    \\\" if item else \\\"|   \\\" for item in ancestors_last) + (\\\"`-- \\\" if last else \\\"|-- \\\")\",\"\",\"\",\"def unicode_tree_prefix(ancestors_last: Sequence[bool], last: bool) -> str:\",\"    return \\\"\\\".join(\\\"    \\\" if item else \\\"│   \\\" for item in ancestors_last) + (\\\"└── \\\" if last else \\\"├── \\\")\",\"\",\"\",\"def flatten_tree(\",\"    entry: Entry,\",\"    cfg: Config,\",\"    rows: list[TreeRow],\",\"    depth: int,\",\"    ancestors_last: tuple[bool, ...],\",\"    last: bool,\",\"    visited: set[str],\",\") -> None:\",\"    prefix = \\\"\\\" if depth == 0 else unicode_tree_prefix(ancestors_last, last)\",\"    rows.append(TreeRow(entry, prefix))\",\"    if cfg.level is not None and depth >= cfg.level:\",\"        return\",\"    can_descend = entry.is_directory() or (\",\"        cfg.follow_symlinks and entry.is_link() and entry.points_to_directory()\",\"    )\",\"    if not can_descend or entry.synthetic:\",\"        return\",\"    try:\",\"        identity = os.path.realpath(entry.path).casefold()\",\"    except OSError:\",\"        identity = os.path.abspath(entry.path).casefold()\",\"    if identity in visited:\",\"        return\",\"    visited.add(identity)\",\"    children, _error = scan_directory(entry.path, cfg, recursing=True)\",\"    for index, child in enumerate(children):\",\"        child_last = index == len(children) - 1\",\"        flatten_tree(\",\"            child,\",\"            cfg,\",\"            rows,\",\"            depth + 1,\",\"            ancestors_last + ((last,) if depth > 0 else ()),\",\"            child_last,\",\"            visited,\",\"        )\",\"    visited.remove(identity)\",\"\",\"\",\"def render_tree(entries: list[Entry], cfg: Config) -> list[str]:\",\"    entries = sort_entries(entries, cfg)\",\"    rows: list[TreeRow] = []\",\"    for index, entry in enumerate(entries):\",\"        flatten_tree(entry, cfg, rows, 0, (), index == len(entries) - 1, set())\",\"    if cfg.table:\",\"        return render_details(rows, cfg)\",\"    return [row.prefix + render_name(row.entry, cfg, show_link=True) for row in rows]\",\"\",\"\",\"def rust_path_debug(path: str) -> str:\",\"    escaped_path = (\",\"        path.replace(\\\"\\\\\\\\\\\", \\\"\\\\\\\\\\\\\\\\\\\")\",\"        .replace('\\\"', '\\\\\\\\\\\"')\",\"        .replace(\\\"\\\\n\\\", \\\"\\\\\\\\n\\\")\",\"        .replace(\\\"\\\\r\\\", \\\"\\\\\\\\r\\\")\",\"        .replace(\\\"\\\\t\\\", \\\"\\\\\\\\t\\\")\",\"    )\",\"    return f'\\\"{escaped_path}\\\"'\",\"\",\"\",\"def os_error_message(path: str, error: OSError) -> str:\",\"    code = getattr(error, \\\"winerror\\\", None) or error.errno or 1\",\"    text = error.strerror or str(error)\",\"    if os.name == \\\"nt\\\":\",\"        try:\",\"            text = ctypes.FormatError(code).strip()\",\"        except (ValueError, OSError):\",\"            pass\",\"    return f\\\"{rust_path_debug(path)}: {text} (os error {code})\\\"\",\"\",\"\",\"def directory_header(path: str, cfg: Config) -> str:\",\"    return quote(path, cfg.no_quotes) + \\\":\\\"\",\"\",\"\",\"def recurse_directories(\",\"    directories: Sequence[Entry],\",\"    cfg: Config,\",\"    output: list[str],\",\"    errors: list[str],\",\"    depth: int,\",\"    visited: set[str],\",\") -> None:\",\"    if cfg.level is not None and depth >= cfg.level:\",\"        return\",\"    for directory in directories:\",\"        if directory.synthetic or not directory.points_to_directory():\",\"            continue\",\"        if directory.is_link() and not cfg.follow_symlinks:\",\"            continue\",\"        identity = os.path.realpath(directory.path).casefold()\",\"        if identity in visited:\",\"            continue\",\"        visited.add(identity)\",\"        output.append(\\\"\\\")\",\"        output.append(directory_header(directory.path, cfg))\",\"        children, error = scan_directory(directory.path, cfg, recursing=True)\",\"        if error is not None:\",\"            errors.append(os_error_message(directory.path, error))\",\"            visited.remove(identity)\",\"            continue\",\"        output.extend(render_entries(children, cfg, directory.path))\",\"        nested = [\",\"            child\",\"            for child in children\",\"            if child.points_to_directory() and not child.synthetic\",\"        ]\",\"        recurse_directories(nested, cfg, output, errors, depth + 1, visited)\",\"        visited.remove(identity)\",\"\",\"\",\"def run_listing(cfg: Config) -> tuple[int, list[str], list[str]]:\",\"    paths = list(cfg.paths)\",\"    if not paths:\",\"        if cfg.has(\\\"stdin\\\"):\",\"            separator = os.environ.get(\\\"EZA_STDIN_SEPARATOR\\\", \\\"\\\\n\\\")\",\"            data = sys.stdin.buffer.read().decode(\\\"utf-8\\\")\",\"            paths = [item for item in data.split(separator) if item]\",\"        else:\",\"            paths = [\\\".\\\"]\",\"\",\"    valid: list[Entry] = []\",\"    errors: list[str] = []\",\"    status = 0\",\"    for path in paths:\",\"        entry = make_entry(path, cfg=cfg)\",\"        try:\",\"            entry.metadata()\",\"        except OSError as error:\",\"            errors.append(os_error_message(path, error))\",\"            status = 2\",\"            continue\",\"        valid.append(entry)\",\"\",\"    valid = [entry for entry in valid if not ignored(entry.name, cfg)]\",\"    if cfg.tree:\",\"        return status, render_tree(valid, cfg), errors\",\"\",\"    files: list[Entry] = []\",\"    directories: list[Entry] = []\",\"    for entry in valid:\",\"        if entry.points_to_directory() and not cfg.treat_dirs:\",\"            directories.append(entry)\",\"        else:\",\"            files.append(entry)\",\"\",\"    output: list[str] = []\",\"    if files:\",\"        output.extend(render_entries(files, cfg))\",\"\",\"    no_files = not files\",\"    only_directory = len(directories) == 1 and no_files\",\"    first = no_files\",\"    for directory in directories:\",\"        if not first:\",\"            output.append(\\\"\\\")\",\"        first = False\",\"        if not only_directory:\",\"            output.append(directory_header(directory.path, cfg))\",\"        children, error = scan_directory(directory.path, cfg, recursing=cfg.recurse)\",\"        if error is not None:\",\"            errors.append(os_error_message(directory.path, error))\",\"            status = 13 if isinstance(error, PermissionError) else max(status, 2)\",\"            continue\",\"        output.extend(render_entries(children, cfg, directory.path))\",\"        if cfg.recurse:\",\"            nested = [\",\"                child\",\"                for child in children\",\"                if child.points_to_directory() and not child.synthetic\",\"            ]\",\"            recurse_directories(nested, cfg, output, errors, 0, {os.path.realpath(directory.path).casefold()})\",\"\",\"    return status, output, errors\",\"\",\"\",\"def write_bytes(stream, text: str) -> None:\",\"    stream.buffer.write(text.encode(\\\"utf-8\\\", \\\"replace\\\"))\",\"    stream.buffer.flush()\",\"\",\"\",\"def main(argv: Optional[Sequence[str]] = None) -> int:\",\"    if argv is None:\",\"        argv = sys.argv[1:]\",\"    try:\",\"        occurrences, paths = parse_arguments(argv)\",\"        if any(item.canonical == \\\"help\\\" for item in occurrences):\",\"            write_bytes(sys.stdout, HELP)\",\"            return 0\",\"        if any(item.canonical == \\\"version\\\" for item in occurrences):\",\"            write_bytes(sys.stdout, VERSION)\",\"            return 0\",\"        cfg = make_config(occurrences, paths)\",\"        status, output, errors = run_listing(cfg)\",\"        if output:\",\"            write_bytes(sys.stdout, \\\"\\\\n\\\".join(output) + \\\"\\\\n\\\")\",\"        if errors:\",\"            write_bytes(sys.stderr, \\\"\\\\n\\\".join(errors) + \\\"\\\\n\\\")\",\"        return status\",\"    except CliError as error:\",\"        write_bytes(sys.stderr, f\\\"eza: {error}\\\\n\\\")\",\"        return 3\",\"    except BrokenPipeError:\",\"        return 0\",\"\",\"\",\"if __name__ == \\\"__main__\\\":\",\"    raise SystemExit(main())\"],\"path\":\"eza_port.py\"}],\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"Success. Updated files.\"}","changes":[{"kind":"add","lines":["#!/usr/bin/env python3","\"\"\"Focused Python port of eza 0.23.3 for the benchmark CLI surface.\"\"\"","","from __future__ import annotations","","import ctypes","import datetime as dt","import fnmatch","import math","import os","import re","import shutil","import stat","import sys","import unicodedata","from dataclasses import dataclass, field","from functools import cached_property","from typing import Iterable, Optional, Sequence","","","VERSION = \"\"\"eza - A modern, maintained replacement for ls","v0.23.3 [+git]","https://github.com/eza-community/eza","\"\"\"","","HELP = \"\"\"Usage:","  eza [options] [files...]","","META OPTIONS","  -?, --help                 show list of command-line options","  -v, --version              show version of eza","","DISPLAY OPTIONS","  -1, --oneline              display one entry per line","  -l, --long                 display extended file metadata as a table","  -G, --grid                 display entries as a grid (default)","  -x, --across               sort the grid across, rather than downwards","  -R, --recurse              recurse into directories","  -T, --tree                 recurse into directories as a tree","  -X, --dereference          dereference symbolic links when displaying information","  -F, --classify=WHEN        display type indicator by file names (always, auto, never)","  --colo[u]r=WHEN            when to use terminal colours (always, auto, never)","  --colo[u]r-scale           highlight levels of 'field' distinctly(all, age, size)","  --colo[u]r-scale-mode      use gradient or fixed colors in --color-scale (fixed, gradient)","  --icons=WHEN               when to display icons (always, auto, never)","  --no-quotes                don't quote file names with spaces","  --hyperlink                display entries as hyperlinks","  --absolute                 display entries with their absolute path (on, follow, off)","  --follow-symlinks          drill down into symbolic links that point to directories","  -w, --width COLS           set screen width in columns","","","FILTERING AND SORTING OPTIONS","  -a, --all                  show hidden and 'dot' files. Use this twice to also","                             show the '.' and '..' directories","  -A, --almost-all           equivalent to --all; included for compatibility with `ls -A`","  -d, --treat-dirs-as-files  list directories as files; don't list their contents","  -D, --only-dirs            list only directories","  -f, --only-files           list only files","  --show-symlinks            explicitly show symbolic links (for use with --only-dirs | --only-files)","  --no-symlinks              do not show symbolic links","  -L, --level DEPTH          limit the depth of recursion","  -r, --reverse              reverse the sort order","  -s, --sort SORT_FIELD      which field to sort by","  --group-directories-first  list directories before other files","  --group-directories-last   list directories after other files","  -I, --ignore-glob GLOBS    glob patterns (pipe-separated) of files to ignore","  --git-ignore               ignore files mentioned in '.gitignore'","  Valid sort fields:         name, Name, extension, Extension, size, type,","                             created, modified, accessed, changed, inode, and none.","                             date, time, old, and new all refer to modified.","","LONG VIEW OPTIONS","  -b, --binary               list file sizes with binary prefixes","  -B, --bytes                list file sizes in bytes, without any prefixes","  -g, --group                list each file's group","  --smart-group              only show group if it has a different name from owner","  -h, --header               add a header row to each column","  -H, --links                list each file's number of hard links","  -i, --inode                list each file's inode number","  -M, --mounts               show mount details (Linux and Mac only)","  -n, --numeric              list numeric user and group IDs","  -O, --flags                list file flags (Mac, BSD, and Windows only)","  -S, --blocksize            show size of allocated file system blocks","  -t, --time FIELD           which timestamp field to list (modified, accessed, created)","  -m, --modified             use the modified timestamp field","  -u, --accessed             use the accessed timestamp field","  -U, --created              use the created timestamp field","  --changed                  use the changed timestamp field","  --time-style               how to format timestamps (default, iso, long-iso,","                             full-iso, relative, or a custom style '+<FORMAT>'","                             like '+%Y-%m-%d %H:%M')","  --total-size               show the size of a directory as the size of all","                             files and directories inside (unix only)","  -o, --octal-permissions    list each file's permission in octal format","  --no-permissions           suppress the permissions field","  --no-filesize              suppress the filesize field","  --no-user                  suppress the user field","  --no-time                  suppress the time field","  --stdin                    read file names from stdin, one per line or other separator ","                             specified in environment","  --git                      list each file's Git status, if tracked or ignored","  --no-git                   suppress Git status (always overrides --git,","                             --git-repos, --git-repos-no-status)","  --git-repos                list root of git-tree status","  --git-repos-no-status      list each git-repos branch name (much faster)","    ","  -@, --extended             list each file's extended attributes and sizes","  -Z, --context              list each file's security context","\"\"\"","","","FILE_ATTRIBUTE_READONLY = 0x00000001","FILE_ATTRIBUTE_HIDDEN = 0x00000002","FILE_ATTRIBUTE_SYSTEM = 0x00000004","FILE_ATTRIBUTE_DIRECTORY = 0x00000010","FILE_ATTRIBUTE_ARCHIVE = 0x00000020","FILE_ATTRIBUTE_TEMPORARY = 0x00000100","FILE_ATTRIBUTE_REPARSE_POINT = 0x00000400","FILE_ATTRIBUTE_COMPRESSED = 0x00000800","FILE_ATTRIBUTE_OFFLINE = 0x00001000","FILE_ATTRIBUTE_NOT_CONTENT_INDEXED = 0x00002000","FILE_ATTRIBUTE_ENCRYPTED = 0x00004000","FILE_ATTRIBUTE_NO_SCRUB_DATA = 0x00020000","FILE_ATTRIBUTE_PINNED = 0x00080000","FILE_ATTRIBUTE_UNPINNED = 0x00100000","FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS = 0x00400000","","","SORT_CHOICES = (","    \"name\",","    \"Name\",","    \"size\",","    \"extension\",","    \"Extension\",","    \"modified