\"header\"],","    \"i\": LONG_SPECS[\"inode\"],","    \"H\": LONG_SPECS[\"links\"],","    \"m\": LONG_SPECS[\"modified\"],","    \"S\": LONG_SPECS[\"blocksize\"],","    \"t\": LONG_SPECS[\"time\"],","    \"u\": LONG_SPECS[\"accessed\"],","    \"U\": LONG_SPECS[\"created\"],","    \"M\": LONG_SPECS[\"mounts\"],","    \"O\": LONG_SPECS[\"flags\"],","    \"o\": LONG_SPECS[\"octal-permissions\"],","    \"@\": LONG_SPECS[\"extended\"],","    \"Z\": LONG_SPECS[\"context\"],","}","","","@dataclass(frozen=True)","class Occurrence:","    canonical: str","    value: Optional[str]","    position: int","    spelling: str","","","class CliError(Exception):","    pass","","","def option_label(canonical: str) -> str:","    short_for = {","        \"sort\": \"s\",","        \"level\": \"L\",","        \"width\": \"w\",","        \"time\": \"t\",","    }","    suffix = f\" (-{short_for[canonical]})\" if canonical in short_for else \"\"","    return f\"--{canonical}{suffix}\"","","","def unknown_argument(arg: str) -> CliError:","    return CliError(f\"Unknown argument {arg}\")","","","def needs_value(spelling: str, spec: OptionSpec) -> CliError:","    choices = f\" (choices: {', '.join(spec.choices)})\" if spec.choices else \"\"","    return CliError(f\"Flag {spelling} needs a value{choices}\")","","","def parse_arguments(argv: Sequence[str]) -> tuple[list[Occurrence], list[str]]:","    occurrences: list[Occurrence] = []","    paths: list[str] = []","    i = 0","    position = 0","    options_done = False","","    while i < len(argv):","        token = argv[i]","        if options_done or token == \"-\" or not token.startswith(\"-\"):","            paths.append(token)","            i += 1","            continue","        if token == \"--\":","            options_done = True","            i += 1","            continue","","        if token.startswith(\"--\"):","            body = token[2:]","            name, equal, attached = body.partition(\"=\")","            spec = LONG_SPECS.get(name)","            if spec is None:","                raise unknown_argument(f\"--{name}\")","            spelling = f\"--{name}\"","            value: Optional[str] = None","            if spec.value_kind == \"none\":","                if equal:","                    raise CliError(f\"Flag {spelling} cannot take a value\")","            elif spec.value_kind == \"required\":","                if equal:","                    value = attached","                elif i + 1 < len(argv):","                    i += 1","                    value = argv[i]","                else:","                    raise needs_value(spelling, spec)","            else:","                if equal:","                    value = attached","                elif i + 1 < len(argv) and argv[i + 1] in spec.choices:","                    i += 1","                    value = argv[i]","                else:","                    value = spec.default","            occurrences.append(Occurrence(spec.canonical, value, position, spelling))","            position += 1","            i += 1","            continue","","        cluster = token[1:]","        j = 0","        while j < len(cluster):","            short = cluster[j]","            if short == \"=\":","                raise unknown_argument(\"-=\")","            spec = SHORT_SPECS.get(short)","            if spec is None:","                raise unknown_argument(f\"-{short}\")","            spelling = f\"-{short}\"","            value = None","            if spec.value_kind == \"none\":","                occurrences.append(Occurrence(spec.canonical, None, position, spelling))","                position += 1","                j += 1","                continue","","            rest = cluster[j + 1 :]","            if rest.startswith(\"=\"):","                rest = rest[1:]","            if spec.value_kind == \"required\":","                if rest:","                    value = rest","                elif i + 1 < len(argv):","                    i += 1","                    value = argv[i]","                else:","                    raise needs_value(spelling, spec)","            else:","                if rest:","                    if rest not in spec.choices:","                        raise CliError(f\"Flag {spelling} cannot take a value\")","                    value = rest","                elif i + 1 < len(argv) and argv[i + 1] in spec.choices:","                    i += 1","                    value = argv[i]","                else:","                    value = spec.default","            occurrences.append(Occurrence(spec.canonical, value, position, spelling))","            position += 1","            break","        i += 1","","    return occurrences, paths","","","@dataclass","class Config:","    occurrences: list[Occurrence]","    paths: list[str]","    mode: str = \"lines\"","    table: bool = False","    tree: bool = False","    width: Optional[int] = None","    across: bool = False","    recurse: bool = False","    level: Optional[int] = None","    all_count: int = 0","    show_hidden: bool = False","    show_dots: bool = False","    sort_field: str = \"name\"","    sort_upper_first: bool = False","    reverse: bool = False","    dirs_first: bool = False","    dirs_last: bool = False","    only_dirs: bool = False","    only_files: bool = False","    no_symlinks: bool = False","    show_symlinks: bool = False","    ignore_patterns: list[str] = field(default_factory=list)","    treat_dirs: bool = False","    follow_symlinks: bool = False","    dereference: bool = False","    classify: str = \"never\"","    no_quotes: bool = False","    absolute: str = \"off\"","    header: bool = False","    permissions: bool = True","    filesize: bool = True","    file_flags: bool = False","    size_format: str = \"decimal\"","    time_fields: list[str] = field(default_factory=lambda: [\"modified\"])","    time_style: str = \"default\"","","    def has(self, name: str) -> bool:","        return any(o.canonical == name for o in self.occurrences)","","    def count(self, name: str) -> int:","        return sum(o.canonical == name for o in self.occurrences)","","    def last(self, *names: str) -> Optional[Occurrence]:","        choices = [o for o in self.occurrences if o.canonical in names]","        return max(choices, key=lambda o: o.position) if choices else None","","","def parse_nonnegative(value: str, source: str) -> int:","    if not value or not value.isascii() or not value.isdigit():","        raise CliError(","            f'Value \"{value}\" not valid for option {option_label(source)}: '","            \"invalid digit found in string\"","        )","    return int(value)","","","def make_config(occurrences: list[Occurrence], paths: list[str]) -> Config:","    cfg = Config(occurrences, paths)","","    width_occ = cfg.last(\"width\")","    if width_occ is not None:","        cfg.width = parse_nonnegative(width_occ.value or \"\", \"width\")","    elif os.environ.get(\"COLUMNS\"):","        value = os.environ[\"COLUMNS\"]","        if not value.isdigit():","            raise CliError(","                f'Value \"{value}\" not valid for environment variable COLUMNS: '","                \"invalid digit found in string\"","            )","        cfg.width = int(value)","    elif sys.stdout.isatty():","        cfg.width = shutil.get_terminal_size((80, 24)).columns","","    display = cfg.last(\"long\", \"oneline\", \"grid\", \"tree\")","    has_long = cfg.has(\"long\")","    if display is None:","        cfg.mode = \"grid\" if cfg.width is not None else \"lines\"","    elif display.canonical == \"long\" or (","        display.canonical in (\"tree\", \"grid\") and has_long","    ):","        last_structure = cfg.last(\"grid\", \"tree\")","        cfg.mode = (","            \"grid-details\"","            if last_structure is not None and last_structure.canonical == \"grid\"","            else \"details\"","        )","    elif display.canonical == \"tree\":","        cfg.mode = \"details\"","        cfg.tree = True","    elif display.canonical == \"oneline\":","        cfg.mode = \"lines\"","    else:","        cfg.mode = \"grid\"","","    if cfg.has(\"tree\") and cfg.mode == \"details\":","        last_structure = cfg.last(\"tree\", \"grid\")","        cfg.tree = last_structure is not None and last_structure.canonical == \"tree\"","    cfg.table = has_long and cfg.mode in (\"details\", \"grid-details\")","    cfg.across = cfg.has(\"across\")","    cfg.recurse = cfg.has(\"recurse\") or cfg.tree","","    level_occ = cfg.last(\"level\")","    if level_occ is not None and cfg.recurse:","        cfg.level = parse_nonnegative(level_occ.value or \"\", \"level\")","        if cfg.level == 0:","            cfg.level = None","","    cfg.all_count = cfg.count(\"all\")","    cfg.show_hidden = cfg.all_count > 0 or cfg.has(\"almost-all\")","    cfg.show_dots = cfg.all_count >= 2","    if cfg.has(\"tree\") and cfg.show_dots:","        raise CliError(\"Option --tree is useless given --all --all\")","","    sort_occ = cfg.last(\"sort\")","    sort_value = sort_occ.value if sort_occ else \"name\"","    if sort_value == \"inode\" and os.name == \"nt\":","        sort_spec = None","    else:","        sort_spec = SORT_ALIASES.get(sort_value or \"\")","    if sort_spec is None:","        choices = \", \".join(SORT_CHOICES)","        raise CliError(","            f'Option --sort (-s) has no \"{sort_value}\" setting (choices: {choices})'","        )","    cfg.sort_field, cfg.sort_upper_first = sort_spec","","    cfg.reverse = cfg.has(\"reverse\")","    cfg.dirs_first = cfg.has(\"dirs-first\")","    cfg.dirs_last = cfg.has(\"dirs-last\")","    cfg.only_dirs = cfg.has(\"only-dirs\")","    cfg.only_files = cfg.has(\"only-files\")","    cfg.no_symlinks = cfg.has(\"no-symlinks\")","    cfg.show_symlinks = cfg.has(\"show-symlinks\")","    cfg.treat_dirs = cfg.has(\"treat-dirs-as-files\") or cfg.has(\"list-dirs\")","    cfg.follow_symlinks = cfg.has(\"follow-symlinks\")","    cfg.dereference = cfg.has(\"dereference\")","","    for occurrence in occurrences:","        if occurrence.canonical == \"ignore-glob\" and occurrence.value is not None:","            cfg.ignore_patterns.extend(occurrence.value.split(\"|\"))","","    classify = cfg.last(\"classify\")","    if classify:","        value = classify.value or \"auto\"","        if value not in (\"always\", \"auto\", \"automatic\", \"never\"):","            raise CliError(f'Option --classify (-F) has no \"{value}\" setting')","        cfg.classify = \"always\" if value == \"always\" else \"never\"","","    absolute = cfg.last(\"absolute\")","    if absolute:","        value = absolute.value or \"on\"","        if value not in (\"on\", \"yes\", \"follow\", \"off\", \"no\"):","            raise CliError(f'Option --absolute has no \"{value}\" setting')","        cfg.absolute = \"off\" if value in (\"off\", \"no\") else value","","    cfg.no_quotes = cfg.has(\"no-quotes\")","    cfg.header = cfg.has(\"header\") and cfg.table","    cfg.permissions = not cfg.has(\"no-permissions\")","    cfg.filesize = not cfg.has(\"no-filesize\")","    cfg.file_flags = cfg.has(\"flags\")","","    size_occ = cfg.last(\"binary\", \"bytes\")","    if size_occ and size_occ.canonical == \"binary\":","        cfg.size_format = \"binary\"","    elif size_occ and size_occ.canonical == \"bytes\":","        cfg.size_format = \"bytes\"","","    explicit_times: list[str] = []","    time_value = cfg.last(\"time\")","    if time_value:","        if time_value.value not in (\"modified\", \"changed\", \"accessed\", \"created\"):","            choices = \"modified, changed, accessed, created\"","            raise CliError(","                f'Option --time (-t) has no \"{time_value.value}\" setting '","                f\"(choices: {choices})\"","            )","        explicit_times.append(time_value.value or \"modified\")","    for name in (\"modified\", \"changed\", \"created\", \"accessed\"):","        if cfg.has(name) and name not in explicit_times:","            explicit_times.append(name)","    if explicit_times:","        cfg.time_fields = [","            name","            for name in (\"modified\", \"changed\", \"created\", \"accessed\")","            if name in explicit_times","        ]","    if cfg.has(\"no-time\"):","        cfg.time_fields = []","","    style_occ = cfg.last(\"time-style\")","    if style_occ and cfg.table:","        value = style_occ.value or \"\"","        if value not in (\"default\", \"iso\", \"long-iso\", \"full-iso\", \"relative\") and not value.startswith(\"+\"):","            choices = \"default, long-iso, full-iso, iso, relative\"","            raise CliError(","                f'Option --time-style has no \"{value}\" setting (choices: {choices})'","            )","        cfg.time_style = value","    elif cfg.table and os.environ.get(\"TIME_STYLE\"):","        cfg.time_style = os.environ[\"TIME_STYLE\"]","","    return cfg","","","_MISSING = object()","","","@dataclass","class Entry:","    path: str","    name: str","    parent_dir: Optional[str] = None","    synthetic: bool = False","    dereference: bool = False","    _lstat_value: object = field(default=_MISSING, repr=False)","    _stat_value: object = field(default=_MISSING, repr=False)","","    def lstat(self):","        if self._lstat_value is _MISSING:","            self._lstat_value = os.lstat(self.path)","        return self._lstat_value","","    def metadata(self):","        if not self.dereference:","            return self.lstat()","        if self._stat_value is _MISSING:","            self._stat_value = os.stat(self.path)","        return self._stat_value","","    def is_link(self) -> bool:","        try:","            return os.path.islink(self.path) or stat.S_ISLNK(self.lstat().st_mode)","        except OSError:","            return False","","    def is_directory(self) -> bool:","        if self.is_link() and not self.dereference:","            return False","        try:","            return stat.S_ISDIR(self.metadata().st_mode)","        except OSError:","            return False","","    def points_to_directory(self) -> bool:","        try:","            return os.path.isdir(self.path)","        except OSError:","            return False","","    def is_file(self) -> bool:","        if self.is_link() and not self.dereference:","            return False","        try:","            return stat.S_ISREG(self.metadata().st_mode)","        except OSError:","            return False","","    def attributes(self) -> int:","        try:","            return int(getattr(self.metadata(), \"st_file_attributes\", 0))","        except OSError:","            return 0","","    def size(self) -> Optional[int]:","        if self.is_directory():","            return None","        try:","            return int(self.metadata().st_size)","        except OSError:","            return 0","","    def time_ns(self, kind: str) -> Optional[int]:","        try:","            metadata = self.metadata()","        except OSError:","            return None","        if kind == \"modified\":","            return int(metadata.st_mtime_ns)","        if kind == \"accessed\":","            return int(metadata.st_atime_ns)","        if kind == \"created\":","            return int(metadata.st_ctime_ns)","        return None","","    def type_rank(self) -> int:","        if self.is_directory():","            return 0","        if self.is_file():","            return 1","        if self.is_link():","            return 2","        return 7","","","def path_name(path: str) -> str:","    trimmed = path.rstrip(\"/\\\\\")","    if not trimmed:","        return path","    name = os.path.basename(trimmed)","    return name if name else trimmed","","","def make_entry(path: str, parent_dir: Optional[str] = None, name: Optional[str] = None, *, cfg: Config) -> Entry:","    return Entry(","        path=path,","        name=path_name(path) if name is None else name,","        parent_dir=parent_dir,","        dereference=cfg.dereference,","    )","","","def display_width(text: str) -> int:","    width = 0","    for char in text:","        if unicodedata.combining(char):","            continue","        width += 2 if unicodedata.east_asian_width(char) in (\"W\", \"F\") else 1","    return width","","","def escaped(text: str) -> str:","    replacements = {","        \"\\n\": r\"\\n\",","        \"\\r\": r\"\\r\",","        \"\\t\": r\"\\t\",","        \"\\x1b\": r\"\\e\",","    }","    bits = []","    for char in text:","        if char in replacements:","            bits.append(replacements[char])","        elif ord(char) < 32 or ord(char) == 127:","            bits.append(f\"\\\\x{ord(char):02x}\")","        else:","            bits.append(char)","    return \"\".join(bits)","","","def quote(text: str, no_quotes: bool = False) -> str:","    text = escaped(text)","    if no_quotes or not any(char.isspace() for char in text):","        return text","    return \"'\" + text.replace(\"'\", \"\\\\'\") + \"'\"","","","def explicit_display_path(entry: Entry, cfg: Config) -> str:","    if cfg.absolute != \"off\":","        result = os.path.realpath(entry.path) if cfg.absolute == \"follow\" else os.path.abspath(entry.path)","        return quote(result, cfg.no_quotes)","    if entry.parent_dir is not None:","        return quote(entry.name, cfg.no_quotes)","    parent = os.path.dirname(entry.path)","    if not parent:","        return quote(entry.name, cfg.no_quotes)","    return quote(parent, cfg.no_quotes) + os.sep + quote(entry.name, cfg.no_quotes)","","","def link_target(entry: Entry) -> Optional[str]:","    if not entry.is_link():","        return None","    try:","        return os.readlink(entry.path)","    except OSError:","        return None","","","def render_name(entry: Entry, cfg: Config, *, show_link: bool) -> str:","    name = explicit_display_path(entry, cfg)","    target = link_target(entry) if show_link else None","    if target is not None:","        target_text = quote(target, False)","        if cfg.classify == \"always\":","            target_path = target if os.path.isabs(target) else os.path.join(os.path.dirname(entry.path), target)","            if os.path.isdir(target_path):","                target_text += \"/\"","        return f\"{name} -> {target_text}\"","    if cfg.classify == \"always\":","        if entry.is_directory():","            name += \"/\"","        elif entry.is_link():","            name += \"@\"","    return name","","","def natural_key(text: str, upper_first: bool = False):","    parts = re.split(r\"(\\d+)\", text)","    key = []","    for part in parts:","        if part.isdigit():","            key.append((0, int(part), len(part)))","        else:","            key.append((1, part if upper_first else part.casefold()))","    return tuple(key)","","","def extension_of(name: str) -> Optional[str]:","    position = name.rfind(\".\")","    return None if position < 0 else name[position + 1 :].lower()","","","def entry_sort_key(entry: Entry, cfg: Config):","    field_name = cfg.sort_field","    if field_name == \"none\":","        return 0","    if field_name in (\"name\", \"hidden-name\"):","        name = entry.name","        if field_name == \"hidden-name\" and name.startswith(\".\"):","            name = name[1:]","        return natural_key(name, cfg.sort_upper_first)","    if field_name == \"extension\":","        extension = extension_of(entry.name)","        if extension is None:","            return (0, (), natural_key(entry.name, cfg.sort_upper_first))","        return (","            1,","            natural_key(extension, cfg.sort_upper_first),","            natural_key(entry.name, cfg.sort_upper_first),","        )","    if field_name == \"size\":","        size = entry.size()","        return (-1 if size is None else size)","    if field_name == \"type\":","        return (entry.type_rank(), natural_key(entry.name, False))","    if field_name == \"age