.append(Entry(path, \".\", path, True, cfg.dereference))","        entries.append(Entry(os.path.join(path, \"..\"), \"..\", path, True, cfg.dereference))","    try:","        with os.scandir(path) as iterator:","            for item in iterator:","                entry = make_entry(item.path, path, item.name, cfg=cfg)","                if not cfg.show_hidden and hidden_entry(entry):","                    continue","                if child_passes(entry, cfg, recursing=recursing):","                    entries.append(entry)","    except OSError as error:","        return [], error","    return sort_entries(entries, cfg), None","","","def grid_lines(cells: Sequence[str], width: int, across: bool, gap: int = 2) -> list[str]:","    if not cells:","        return []","    count = len(cells)","    chosen_rows = count","    chosen_cols = 1","    chosen_widths = [max(display_width(cell) for cell in cells)]","","    for rows in range(1, count + 1):","        cols = math.ceil(count / rows)","        widths = [0] * cols","        for index, cell in enumerate(cells):","            if across:","                col = index % cols","            else:","                col = index // rows","            widths[col] = max(widths[col], display_width(cell))","        total = sum(widths) + gap * (cols - 1)","        if total <= width or cols == 1:","            chosen_rows, chosen_cols, chosen_widths = rows, cols, widths","            break","","    output: list[str] = []","    for row in range(chosen_rows):","        row_cells: list[tuple[int, str]] = []","        for col in range(chosen_cols):","            index = row * chosen_cols + col if across else col * chosen_rows + row","            if index < count:","                row_cells.append((col, cells[index]))","        if not row_cells:","            continue","        bits: list[str] = []","        for cell_index, (col, cell) in enumerate(row_cells):","            bits.append(cell)","            if cell_index < len(row_cells) - 1:","                padding = chosen_widths[col] - display_width(cell) + gap","                bits.append(\" \" * padding)","        output.append(\"\".join(bits))","    return output","","","def windows_mode(entry: Entry) -> str:","    attrs = entry.attributes()","    if entry.is_link():","        kind = \"l\"","    elif entry.is_directory():","        kind = \"d\"","    else:","        kind = \"-\"","    return \"\".join(","        (","            kind,","            \"a\" if attrs & FILE_ATTRIBUTE_ARCHIVE else \"-\",","            \"r\" if attrs & FILE_ATTRIBUTE_READONLY else \"-\",","            \"h\" if attrs & FILE_ATTRIBUTE_HIDDEN else \"-\",","            \"s\" if attrs & FILE_ATTRIBUTE_SYSTEM else \"-\",","        )","    )","","","def file_flags(entry: Entry) -> str:","    attrs = entry.attributes()","    ordered = (","        (FILE_ATTRIBUTE_READONLY, \"readonly\"),","        (FILE_ATTRIBUTE_HIDDEN, \"hidden\"),","        (FILE_ATTRIBUTE_SYSTEM, \"system\"),","        (FILE_ATTRIBUTE_ARCHIVE, \"archive\"),","        (FILE_ATTRIBUTE_TEMPORARY, \"temporary\"),","        (FILE_ATTRIBUTE_COMPRESSED, \"compressed\"),","        (FILE_ATTRIBUTE_OFFLINE, \"offline\"),","        (FILE_ATTRIBUTE_NOT_CONTENT_INDEXED, \"not indexed\"),","        (FILE_ATTRIBUTE_ENCRYPTED, \"encrypted\"),","        (FILE_ATTRIBUTE_NO_SCRUB_DATA, \"no scrub\"),","        (FILE_ATTRIBUTE_UNPINNED, \"unpinned\"),","        (FILE_ATTRIBUTE_PINNED, \"pinned\"),","        (FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS, \"recall on data access\"),","    )","    names = [name for flag_value, name in ordered if attrs & flag_value]","    return \"-\" if not names else \"-\".join(names)","","","def formatted_size(entry: Entry, mode: str) -> str:","    size = entry.size()","    if size is None:","        return \"-\"","    if mode == \"bytes\":","        return f\"{size:,}\"","    base = 1024 if mode == \"binary\" else 1000","    symbols = (\"\", \"Ki\", \"Mi\", \"Gi\", \"Ti\", \"Pi\", \"Ei\") if mode == \"binary\" else (\"\", \"k\", \"M\", \"G\", \"T\", \"P\", \"E\")","    if size < base:","        return f\"{size:,}\"","    exponent = min(int(math.log(size, base)), len(symbols) - 1)","    number = size / (base**exponent)","    rendered = f\"{number:.1f}\" if number < 10 else f\"{math.floor(number + 0.5):,}\"","    return rendered + symbols[exponent]","","","def fixed_local_datetime(timestamp_ns: int) -> tuple[dt.datetime, dt.timedelta]:","    timestamp = timestamp_ns / 1_000_000_000","    utc = dt.datetime.fromtimestamp(timestamp, dt.timezone.utc).replace(tzinfo=None)","    offset = dt.datetime.now().astimezone().utcoffset() or dt.timedelta(0)","    return utc + offset, offset","","","def relative_time(value: dt.datetime) -> str:","    now = dt.datetime.now()","    seconds = max(0, int((now - value).total_seconds()))","    ranges = (","        (365 * 86400, \"year\"),","        (30 * 86400, \"month\"),","        (7 * 86400, \"week\"),","        (86400, \"day\"),","        (3600, \"hour\"),","        (60, \"minute\"),","    )","    for divisor, label in ranges:","        if seconds >= divisor:","            amount = max(1, math.floor(seconds / divisor + 0.5))","            return f\"{amount} {label}{'' if amount == 1 else 's'}\"","    return \"now\"","","","def chrono_custom(value: dt.datetime, pattern: str) -> str:","    pattern = pattern.replace(\"%_d\", \"{EZA_DAY}\").replace(\"%f\", \"{EZA_NANO}\")","    output = value.strftime(pattern)","    output = output.replace(\"{EZA_DAY}\", f\"{value.day:2d}\")","    output = output.replace(\"{EZA_NANO}\", f\"{value.microsecond * 1000:09d}\")","    return output","","","def formatted_time(entry: Entry, kind: str, style: str) -> str:","    timestamp_ns = entry.time_ns(kind)","    if timestamp_ns is None:","        return \"-\"","    value, offset = fixed_local_datetime(timestamp_ns)","    current_year = dt.datetime.now().year","    if style == \"default\":","        if value.year == current_year:","            return f\"{value.day:2d} {value.strftime('%b')} {value:%H:%M}\"","        return f\"{value.day:2d} {value.strftime('%b')}  {value:%Y}\"","    if style == \"iso\":","        return value.strftime(\"%m-%d %H:%M\" if value.year == current_year else \"%Y-%m-%d\")","    if style == \"long-iso\":","        return value.strftime(\"%Y-%m-%d %H:%M\")","    if style == \"full-iso\":","        total_minutes = int(offset.total_seconds() // 60)","        sign = \"+\" if total_minutes >= 0 else \"-\"","        total_minutes = abs(total_minutes)","        zone = f\"{sign}{total_minutes // 60:02d}{total_minutes % 60:02d}\"","        nanos = timestamp_ns % 1_000_000_000","        return value.strftime(\"%Y-%m-%d %H:%M:%S\") + f\".{nanos:09d} {zone}\"","    if style == \"relative\":","        return relative_time(value)","    if style.startswith(\"+\"):","        formats = style[1:].split(\"\\n\")","        pattern = formats[1] if len(formats) > 1 and value.year == current_year else formats[0]","        return chrono_custom(value, pattern)","    return formatted_time(entry, kind, \"default\")","","","@dataclass(frozen=True)","class Column:","    key: str","    header: str","    alignment: str","","","def columns_for(cfg: Config) -> list[Column]:","    columns: list[Column] = []","    if cfg.permissions:","        columns.append(Column(\"mode\", \"Mode\", \"left\"))","    if cfg.filesize:","        columns.append(Column(\"size\", \"Size\", \"right\"))","    if cfg.file_flags:","        columns.append(Column(\"flags\", \"Flags\", \"left\"))","    for kind in cfg.time_fields:","        columns.append(Column(f\"time:{kind}\", f\"Date {kind.capitalize()}\", \"right\"))","    return columns","","","def column_value(entry: Entry, column: Column, cfg: Config) -> str:","    if column.key == \"mode\":","        return windows_mode(entry)","    if column.key == \"size\":","        return formatted_size(entry, cfg.size_format)","    if column.key == \"flags\":","        return file_flags(entry)","    if column.key.startswith(\"time:\"):","        return formatted_time(entry, column.key.split(\":\", 1)[1], cfg.time_style)","    return \"-\"","","","@dataclass(frozen=True)","class TreeRow:","    entry: Entry","    prefix: str","","","def prepare_table(rows: Sequence[TreeRow], cfg: Config):","    columns = columns_for(cfg)","    values = [[column_value(row.entry, column, cfg) for column in columns] for row in rows]","    widths = [0] * len(columns)","    for index, column in enumerate(columns):","        if cfg.header:","            widths[index] = display_width(column.header)","        for row_values in values:","            widths[index] = max(widths[index], display_width(row_values[index]))","    return columns, values, widths","","","def render_metadata(values: Sequence[str], columns: Sequence[Column], widths: Sequence[int]) -> str:","    bits: list[str] = []","    for value, column, width in zip(values, columns, widths):","        padding = width - display_width(value)","        if column.alignment == \"right\":","            bits.append(\" \" * padding + value)","        else:","            bits.append(value + \" \" * padding)","        bits.append(\" \")","    return \"\".join(bits)","","","def render_details(rows: Sequence[TreeRow], cfg: Config) -> list[str]:","    columns, values, widths = prepare_table(rows, cfg)","    output: list[str] = []","    if cfg.header:","        header_values = [column.header for column in columns]","        output.append(render_metadata(header_values, columns, widths) + \"Name\")","    for row, row_values in zip(rows, values):","        metadata = render_metadata(row_values, columns, widths)","        output.append(metadata + row.prefix + render_name(row.entry, cfg, show_link=True))","    return output","","","def render_entries(entries: list[Entry], cfg: Config, parent: Optional[str] = None) -> list[str]:","    entries = sort_entries(entries, cfg)","    if cfg.mode == \"lines\":","        return [render_name(entry, cfg, show_link=True) for entry in entries]","    if cfg.mode == \"grid\":","        width = cfg.width if cfg.width is not None else 80","        cells = [render_name(entry, cfg, show_link=False) for entry in entries]","        return grid_lines(cells, width, cfg.across)","    rows = [TreeRow(entry, \"\") for entry in entries]","    if cfg.mode == \"grid-details\" and cfg.width is not None:","        columns, values, widths = prepare_table(rows, cfg)","        cells = []","        for row, row_values in zip(rows, values):","            details = render_metadata(row_values, columns, widths)","            cells.append(details + \" \" + render_name(row.entry, cfg, show_link=False))","        threshold = os.environ.get(\"EZA_GRID_ROWS\") or os.environ.get(\"EXA_GRID_ROWS\")","        lines = grid_lines(cells, cfg.width, False, 4)","        if threshold and threshold.isdigit() and len(lines) < int(threshold):","            return render_details(rows, cfg)","        if cfg.header and columns:","            combined = render_metadata([column.header for column in columns], columns, widths) + \"Name\"","            return [combined] + lines","        return lines","    return render_details(rows, cfg)","","","def tree_prefix(ancestors_last: Sequence[bool], last: bool) -> str:","    return \"\".join(\"    \" if item else \"|   \" for item in ancestors_last) + (\"`-- \" if last else \"|-- \")","","","def unicode_tree_prefix(ancestors_last: Sequence[bool], last: bool) -> str:","    return \"\".join(\"    \" if item else \"│   \" for item in ancestors_last) + (\"└── \" if last else \"├── \")","","","def flatten_tree(","    entry: Entry,","    cfg: Config,","    rows: list[TreeRow],","    depth: int,","    ancestors_last: tuple[bool, ...],","    last: bool,","    visited: set[str],",") -> None:","    prefix = \"\" if depth == 0 else unicode_tree_prefix(ancestors_last, last)","    rows.append(TreeRow(entry, prefix))","    if cfg.level is not None and depth >= cfg.level:","        return","    can