directory_header(path: str, cfg: Config) -> str:","    return quote(path, cfg.no_quotes) + \":\"","","","def recurse_directories(","    directories: Sequence[Entry],","    cfg: Config,","    output: list[str],","    errors: list[str],","    depth: int,","    visited: set[str],",") -> None:","    if cfg.level is not None and depth >= cfg.level:","        return","    for directory in directories:","        if directory.synthetic or not directory.points_to_directory():","            continue","        if directory.is_link() and not cfg.follow_symlinks:","            continue","        identity = os.path.realpath(directory.path).casefold()","        if identity in visited:","            continue","        visited.add(identity)","        output.append(\"\")","        output.append(directory_header(directory.path, cfg))","        children, error = scan_directory(directory.path, cfg, recursing=True)","        if error is not None:","            errors.append(os_error_message(directory.path, error))","            visited.remove(identity)","            continue","        output.extend(render_entries(children, cfg, directory.path))","        nested = [","            child","            for child in children","            if child.points_to_directory() and not child.synthetic","        ]","        recurse_directories(nested, cfg, output, errors, depth + 1, visited)","        visited.remove(identity)","","","def run_listing(cfg: Config) -> tuple[int, list[str], list[str]]:","    paths = list(cfg.paths)","    if not paths:","        if cfg.has(\"stdin\"):","            separator = os.environ.get(\"EZA_STDIN_SEPARATOR\", \"\\n\")","            data = sys.stdin.buffer.read().decode(\"utf-8\")","            paths = [item for item in data.split(separator) if item]","        else:","            paths = [\".\"]","","    valid: list[Entry] = []","    errors: list[str] = []","    status = 0","    for path in paths:","        entry = make_entry(path, cfg=cfg)","        try:","            entry.metadata()","        except OSError as error:","            errors.append(os_error_message(path, error))","            status = 2","            continue","        valid.append(entry)","","    valid = [entry for entry in valid if not ignored(entry.name, cfg)]","    if cfg.tree:","        return status, render_tree(valid, cfg), errors","","    files: list[Entry] = []","    directories: list[Entry] = []","    for entry in valid:","        if entry.points_to_directory() and not cfg.treat_dirs:","            directories.append(entry)","        else:","            files.append(entry)","","    output: list[str] = []","    if files:","        output.extend(render_entries(files, cfg))","","    no_files = not files","    only_directory = len(directories) == 1 and no_files","    first = no_files","    for directory in directories:","        if not first:","            output.append(\"\")","        first = False","        if not only_directory:","            output.append(directory_header(directory.path, cfg))","        children, error = scan_directory(directory.path, cfg, recursing=cfg.recurse)","        if error is not None:","            errors.append(os_error_message(directory.path, error))","            status = 13 if isinstance(error, PermissionError) else max(status, 2)","            continue","        output.extend(render_entries(children, cfg, directory.path))","        if cfg.recurse:","            nested = [","                child","                for child in children","                if child.points_to_directory() and not child.synthetic","            ]","            recurse_directories(nested, cfg, output, errors, 0, {os.path.realpath(directory.path).casefold()})","","    return status, output, errors","","","def write_bytes(stream, text: str) -> None:","    stream.buffer.write(text.encode(\"utf-8\", \"replace\"))","    stream.buffer.flush()","","","def main(argv: Optional[Sequence[str]] = None) -> int:","    if argv is None:","        argv = sys.argv[1:]","    try:","        occurrences, paths = parse_arguments(argv)","        if any(item.canonical == \"help\" for item in occurrences):","            write_bytes(sys.stdout, HELP)","            return 0","        if any(item.canonical == \"version\" for item in occurrences):","            write_bytes(sys.stdout, VERSION)","            return 0","        cfg = make_config(occurrences, paths)","        status, output, errors = run_listing(cfg)","        if output:","            write_bytes(sys.stdout, \"\\n\".join(output) + \"\\n\")","        if errors:","            write_bytes(sys.stderr, \"\\n\".join(errors) + \"\\n\")","        return status","    except CliError as error:","        write_bytes(sys.stderr, f\"eza: {error}\\n\")","        return 3","    except BrokenPipeError:","        return 0","","","if __name__ == \"__main__\":","    raise SystemExit(main())"],"path":"eza_port.py"}],"command":"apply_patch","command_index":0,"command_line":"*** Begin Patch\n*** Add File: eza_port.py\n+#!/usr/bin/env python3\n+\"\"\"Focused Python port of eza 0.23.3 for the benchmark CLI surface.\"\"\"\n+\n+from __future__ import annotations\n+\n+import ctypes\n+import datetime as dt\n+import fnmatch\n+import math\n+import os\n+import re\n+import shutil\n+import stat\n+import sys\n+import unicodedata\n+from dataclasses import dataclass, field\n+from functools import cached_property\n+from typing import Iterable, Optional, Sequence\n+\n+\n+VERSION = \"\"\"eza - A modern, maintained replacement for ls\n+v0.23.3 [+git]\n+https://github.com/eza-community/eza\n+\"\"\"\n+\n+HELP = \"\"\"Usage:\n+  eza [options] [files...]\n+\n+META OPTIONS\n+  -?, --help                 show list of command-line options\n+  -v, --version              show version of eza\n+\n+DISPLAY OPTIONS\n+  -1, --oneline              display one entry per line\n+  -l, --long                 display extended file metadata as a table\n+  -G, --grid                 display entries as a grid (default)\n+  -x, --across               sort the grid across, rather than downwards\n+  -R, --recurse              recurse into directories\n+  -T, --tree                 recurse into directories as a tree\n+  -X, --dereference          dereference symbolic links when displaying information\n+  -F, --classify=WHEN        display type indicator by file names (always, auto, never)\n+  --colo[u]r=WHEN            when to use terminal colours (always, auto, never)\n+  --colo[u]r-scale           highlight levels of 'field' distinctly(all, age, size)\n+  --colo[u]r-scale-mode      use gradient or fixed colors in --color-scale (fixed, gradient)\n+  --icons=WHEN               when to display icons (always, auto, never)\n+  --no-quotes                don't quote file names with spaces\n+  --hyperlink                display entries as hyperlinks\n+  --absolute                 display entries with their absolute path (on, follow, off)\n+  --follow-symlinks          drill down into symbolic links that point to directories\n+  -w, --width COLS           set screen width in columns\n+\n+\n+FILTERING AND SORTING OPTIONS\n+  -a, --all                  show hidden and 'dot' files. Use this twice to also\n+                             show the '.' and '..' directories\n+  -A, --almost-all           equivalent to --all; included for compatibility with `ls -A`\n+  -d, --treat-dirs-as-files  list directories as files; don't list their contents\n+  -D, --only-dirs            list only directories\n+  -f, --only-files           list only files\n+  --show-symlinks            explicitly show symbolic links (for use with --only-dirs | --only-files)\n+  --no-symlinks              do not show symbolic links\n+  -L, --level DEPTH          limit the depth of recursion\n+  -r, --reverse              reverse the sort order\n+  -s, --sort SORT_FIELD      which field to sort by\n+  --group-directories-first  list directories before other files\n+  --group-directories-last   list directories after other files\n+  -I, --ignore-glob GLOBS    glob patterns (pipe-separated) of files to ignore\n+  --git-ignore               ignore files mentioned in '.gitignore'\n+  Valid sort fields:         name, Name, extension, Extension, size, type,\n+                             created, modified, accessed, changed, inode, and none.\n+                             date, time, old, and new all refer to modified.\n+\n+LONG VIEW OPTIONS\n+  -b, --binary               list file sizes with binary prefixes\n+  -B, --bytes                list file sizes in bytes, without any prefixes\n+  -g, --group                list each file's group\n+  --smart-group              only show group if it has a different name from owner\n+  -h, --header               add a header row to each column\n+  -H, --links                list each file's number of hard links\n+  -i, --inode                list each file's inode number\n+  -M, --mounts               show mount details (Linux and Mac only)\n+  -n, --numeric              list numeric user and group IDs\n+  -O, --flags                list file flags (Mac, BSD, and Windows only)\n+  -S, --blocksize            show size of allocated file system blocks\n+  -t, --time FIELD           which timestamp field to list (modified, accessed, created)\n+  -m, --modified             use the modified timestamp field\n+  -u, --accessed             use the accessed timestamp field\n+  -U, --created              use the created timestamp field\n+  --changed                  use the changed timestamp field\n+  --time-style               how to format timestamps (default, iso, long-iso,\n+                             full-iso, relative, or a custom style '+<FORMAT>'\n+                             like '+%Y-%m-%d %H:%M')\n+  --total-size               show the size of a directory as the size of all\n+                             files and directories inside (unix only)\n+  -o, --octal-permissions    list each file's permission in octal format\n+  --no-permissions           suppress the permissions field\n+  --no-filesize              suppress the filesize field\n+  --no-user                  suppress the user field\n+  --no-time                  suppress the time field\n+  --stdin                    read file names from stdin, one per line or other separator \n+                             specified in environment\n+  --git                      list each file's Git status, if tracked or ignored\n+  --no-git                   suppress Git status (always overrides --git,\n+                             --git-repos, --git-repos-no-status)\n+  --git-repos                list root of git-tree status\n+  --git-repos-no-status      list each git-repos branch name (much faster)\n+    \n+  -@, --extended             list each file's extended attributes and sizes\n+  -Z, --context              list each file's security context\n+\"\"\"\n+\n+\n+FILE_ATTRIBUTE_READONLY = 0x00000001\n+FILE_ATTRIBUTE_HIDDEN = 0x00000002\n+FILE_ATTRIBUTE_SYSTEM = 0x00000004\n+FILE_ATTRIBUTE_DIRECTORY = 0x00000010\n+FILE_ATTRIBUTE_ARCHIVE = 0x00000020\n+FILE_ATTRIBUTE_TEMPORARY = 0x00000100\n+FILE_ATTRIBUTE_REPARSE_POINT = 0x00000400\n+FILE_ATTRIBUTE_COMPRESSED = 0x00000800\n+FILE_ATTRIBUTE_OFFLINE = 0x00001000\n+FILE_ATTRIBUTE_NOT_CONTENT_INDEXED = 0x00002000\n+FILE_ATTRIBUTE_ENCRYPTED = 0x00004000\n+FILE_ATTRIBUTE_NO_SCRUB_DATA = 0x00020000\n+FILE_ATTRIBUTE_PINNED = 0x00080000\n+FILE_ATTRIBUTE_UNPINNED = 0x00100000\n+FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS = 0x00400000\n+\n+\n+SORT_CHOICES = (\n+    \"name\",\n+    \"Name\",\n+    \"size\",\n+    \"extension\",\n+    \"Extension\",\n+    \"modified\",\n+    \"changed\",\n+    \"accessed\",\n+    \"created\",\n+    \"inode\",\n+    \"type\",\n+    \"none\",\n+)\n+\n+SORT_ALIASES = {\n+    \"name\": (\"name\", False),\n+    \"filename\": (\"name\", False),\n+    \"Name\": (\"name\", True),\n+    \"Filename\": (\"name\", True),\n+    \".name\": (\"hidden-name\", False),\n+    \".filename\": (\"hidden-name\", False),\n+    \".Name\": (\"hidden-name\", True),\n+    \".Filename\": (\"hidden-name\", True),\n+    \"size\": (\"size\", False),\n+    \"filesize\": (\"size\", False),\n+    \"ext\": (\"extension\", False),\n+    \"extension\": (\"extension\", False),\n+    \"Ext\": (\"extension\", True),\n+    \"Extension\": (\"extension\", True),\n+    \"date\": (\"modified\", False),\n+    \"time\": (\"modified\", False),\n+    \"mod\": (\"modified\", False),\n+    \"modified\": (\"modified\", False),\n+    \"new\": (\"modified\", False),\n+    \"newest\": (\"modified\", False),\n+    \"age\": (\"age\", False),\n+    \"old\": (\"age\", False),\n+    \"oldest\": (\"age\", False),\n+    \"ch\": (\"changed\", False),\n+    \"changed\": (\"changed\", False),\n+    \"acc\": (\"accessed\", False),\n+    \"accessed\": (\"accessed\", False),\n+    \"cr\": (\"created\", False),\n+    \"created\": (\"created\", False),\n+    \"type\": (\"type\", False),\n+    \"none\": (\"none\", False),\n+}\n+\n+\n+@dataclass(frozen=True)\n+class OptionSpec:\n+    canonical: str\n+    value_kind: str = \"none\"  # none, required, optional\n+    choices: tuple[str, ...] = ()\n+    default: Optional[str] = None\n+\n+\n+def _spec(name: str, kind: str = \"none\", choices: Sequence[str] = (), default=None):\n+    return OptionSpec(name, kind, tuple(choices), default)\n+\n+\n+WHEN = (\"always\", \"auto\", \"never\")\n+LONG_SPECS = {\n+    \"version\": _spec(\"version\"),\n+    \"help\": _spec(\"help\"),\n+    \"oneline\": _spec(\"oneline\"),\n+    \"long\": _spec(\"long\"),\n+    \"grid\": _spec(\"grid\"),\n+    \"across\": _spec(\"across\"),\n+    \"recurse\": _spec(\"recurse\"),\n+    \"tree\": _spec(\"tree\"),\n+    \"classify\": _spec(\"classify\", \"optional\", WHEN, \"auto\"),\n+    \"dereference\": _spec(\"dereference\"),\n+    \"width\": _spec(\"width\", \"required\"),\n+    \"no-quotes\": _spec(\"no-quotes\"),\n+    \"absolute\": _spec(\"absolute\", \"optional\", (\"on\", \"follow\", \"off\"), \"on\"),\n+    \"follow-symlinks\": _spec(\"follow-symlinks\"),\n+    \"color\": _spec(\"color\", \"optional\", WHEN, \"auto\"),\n+    \"colour\": _spec(\"color\", \"optional\", WHEN, \"auto\"),\n+    \"color-scale\": _spec(\"color-scale\", \"optional\", (\"all\", \"size\", \"age\"), \"all\"),\n+    \"colour-scale\": _spec(\"color-scale\", \"optional\", (\"all\", \"size\", \"age\"), \"all\"),\n+    \"color-scale-mode\": _spec(\"color-scale-mode\", \"required\"),\n+    \"colour-scale-mode\": _spec(\"color-scale-mode\", \"required\"),\n+    \"icons\": _spec(\"icons\", \"optional\", WHEN, \"auto\"),\n+    \"hyperlink\": _spec(\"hyperlink\"),\n+    \"all\": _spec(\"all\"),\n+    \"almost-all\": _spec(\"almost-all\"),\n+    \"treat-dirs-as-files\": _spec(\"treat-dirs-as-files\"),\n+    \"list-dirs\": _spec(\"list-dirs\"),\n+    \"level\": _spec(\"level\", \"required\"),\n+    \"reverse\": _spec(\"reverse\"),\n+    \"sort\": _spec(\"sort\", \"required\", SORT_CHOICES),\n+    \"ignore-glob\": _spec(\"ignore-glob\", \"required\"),\n+    \"git-ignore\": _spec(\"git-ignore\"),\n+    \"group-directories-first\": _spec(\"dirs-first\"),\n+    \"group-directories-last\": _spec(\"dirs-last\"),\n+    \"only-dirs\": _spec(\"only-dirs\"),\n+    \"only-files\": _spec(\"only-files\"),\n+    \"no-symlinks\": _spec(\"no-symlinks\"),\n+    \"show-symlinks\": _spec(\"show-symlinks\"),\n+    \"binary\": _spec(\"binary\"),\n+    \"bytes\": _spec(\"bytes\"),\n+    \"group\": _spec(\"group\"),\n+    \"numeric\": _spec(\"numeric\"),\n+    \"header\": _spec(\"header\"),\n+    \"inode\": _spec(\"inode\"),\n+    \"links\": _spec(\"links\"),\n+    \"modified\": _spec(\"modified\"),\n+    \"changed\": _spec(\"changed\"),\n+    \"blocksize\": _spec(\"blocksize\"),\n+    \"total-size\": _spec(\"total-size\"),\n+    \"time\": _spec(\"time\", \"required\", (\"modified\", \"changed\", \"accessed\", \"created\")),\n+    \"accessed\": _spec(\"accessed\"),\n+    \"created\": _spec(\"created\"),\n+    \"time-style\": _spec(\"time-style\", \"required\"),\n+    \"mounts\": _spec(\"mounts\"),\n+    \"smart-group\": _spec(\"smart-group\"),\n+    \"no-permissions\": _spec(\"no-permissions\"),\n+    \"no-filesize\": _spec(\"no-filesize\"),\n+    \"no-user\": _spec(\"no-user\"),\n+    \"no-time\": _spec(\"no-time\"),\n+    \"flags\": _spec(\"flags\"),\n+    \"octal-permissions\": _spec(\"octal\"),\n+    \"stdin\": _spec(\"stdin\"),\n+    \"git\": _spec(\"git\"),\n+    \"no-git\": _spec(\"no-git\"),\n+    \"git-repos\": _spec(\"git-repos\"),\n+    \"git-repos-no-status\": _spec(\"git-repos-no-status\"),\n+    \"extended\": _spec(\"extended\"),\n+    \"context\": _spec(\"context\"),\n+}\n+\n+SHORT_SPECS = {\n+    \"v\": LONG_SPECS[\"version\"],\n+    \"?\": LONG_SPECS[\"help\"],\n+    \"1\": LONG_SPECS[\"oneline\"],\n+    \"l\": LONG_SPECS[\"long\"],\n+    \"G\": LONG_SPECS[\"grid\"],\n+    \"x\": LONG_SPECS[\"across\"],\n+    \"R\": LONG_SPECS[\"recurse\"],\n+    \"T\": LONG_SPECS[\"tree\"],\n+    \"F\": LONG_SPECS[\"classify\"],\n+    \"X\": LONG_SPECS[\"dereference\"],\n+    \"w\": LONG_SPECS[\"width\"],\n+    \"a\": LONG_SPECS[\"all\"],\n+    \"A\": LONG_SPECS[\"almost-all\"],\n+    \"d\": LONG_SPECS[\"treat-dirs-as-files\"],\n+    \"D\": LONG_SPECS[\"only-dirs\"],\n+    \"f\": LONG_SPECS[\"only-files\"],\n+    \"L\": LONG_SPECS[\"level\"],\n+    \"r\": LONG_SPECS[\"reverse\"],\n+    \"s\": LONG_SPECS[\"sort\"],\n+    \"I\": LONG_SPECS[\"ignore-glob\"],\n+    \"b\": LONG_SPECS[\"binary\"],\n+    \"B\": LONG_SPECS[\"bytes\"],\n+    \"g\": LONG_SPECS[\"group\"],\n+    \"n\": LONG_SPECS[\"numeric\"],\n+    \"h\": LONG_SPECS[\"header\"],\n+    \"i\": LONG_SPECS[\"inode\"],\n+    \"H\": LONG_SPECS[\"links\"],\n+    \"m\": LONG_SPECS[\"modified\"],\n+    \"S\": LONG_SPECS[\"blocksize\"],\n+    \"t\": LONG_SPECS[\"time\"],\n+    \"u\": LONG_SPECS[\"accessed\"],\n+    \"U\": LONG_SPECS[\"created\"],\n+    \"M\": LONG_SPECS[\"mounts\"],\n+    \"O\": LONG_SPECS[\"flags\"],\n+    \"o\": LONG_SPECS[\"octal-permissions\"],\n+    \"@\": LONG_SPECS[\"extended\"],\n+    \"Z\": LONG_SPECS[\"context\"],\n+}\n+\n+\n+@dataclass(frozen=True)\n+class Occurrence:\n+    canonical: str\n+    value: Optional[str]\n+    position: int\n+    spelling: str\n+\n+\n+class CliError(Exception):\n+    pass\n+\n+\n+def option_label(canonical: str) -> str:\n+    short_for = {\n+        \"sort\": \"s\",\n+        \"level\": \"L\",\n+        \"width\": \"w\",\n+        \"time\": \"t\",\n+    }\n+    suffix = f\" (-{short_for[canonical]})\" if canonical in short_for else \"\"\n+    return f\"--{canonical}{suffix}\"\n+\n+\n+def unknown_argument(arg: str) -> CliError:\n+    return CliError(f\"Unknown argument {arg}\")\n+\n+\n+def needs_value(spelling: str, spec: OptionSpec) -> CliError:\n+    choices = f\" (choices: {', '.join(spec.choices)})\" if spec.choices else \"\"\n+    return CliError(f\"Flag {spelling} needs a value{choices}\")\n+\n+\n+def parse_arguments(argv: Sequence[str]) -> tuple[list[Occurrence], list[str]]:\n+    occurrences: list[Occurrence] = []\n+    paths: list[str] = []\n+    i = 0\n+    position = 0\n+    options_done = False\n+\n+    while i < len(argv):\n+        token = argv[i]\n+        if options_done or token == \"-\" or not token.startswith(\"-\"):\n+            paths.append(token)\n+            i += 1\n+            continue\n+        if token == \"--\":\n+            options_done = True\n+            i += 1\n+            continue\n+\n+        if token.startswith(\"--\"):\n+            body = token[2:]\n+            name, equal, attached = body.partition(\"=\")\n+            spec = LONG_SPECS.get(name)\n+            if spec is None:\n+                raise unknown_argument(f\"--{name}\")\n+            spelling = f\"--{name}\"\n+            value: Optional[str] = None\n+            if spec.value_kind == \"none\":\n+                if equal:\n+                    raise CliError(f\"Flag {spelling} cannot take a value\")\n+            elif spec.value_kind == \"required\":\n+                if equal:\n+                    value = attached\n+                elif i + 1 < len(argv):\n+                    i += 1\n+                    value = argv[i]\n+                else:\n+                    raise needs_value(spelling, spec)\n+            else:\n+                if equal:\n+                    value = attached\n+                elif i + 1 < len(argv) and argv[i + 1] in spec.choices:\n+                    i += 1\n+                    value = argv[i]\n+                else:\n+                    value = spec.default\n+            occurrences.append(Occurrence(spec.canonical, value, position, spelling))\n+            position += 1\n+            i += 1\n+            continue\n+\n+        cluster = token[1:]\n+        j = 0\n+        while j < len(cluster):\n+            short = cluster[j]\n+            if short == \"=\":\n+                raise unknown_argument(\"-=\")\n+            spec = SHORT_SPECS.get(short)\n+            if spec is None:\n+                raise unknown_argument(f\"-{short}\")\n+            spelling = f\"-{short}\"\n+            value = None\n+            if spec.value_kind == \"none\":\n+                occurrences.append(Occurrence(spec.canonical, None, position, spelling))\n+                position += 1\n+                j += 1\n+                continue\n+\n+            rest = cluster[j + 1 :]\n+            if rest.startswith(\"=\"):\n+                rest = rest[1:]\n+            if spec.value_kind == \"required\":\n+                if rest:\n+                    value = rest\n+                elif i + 1 < len(argv):\n+                    i += 1\n+                    value = argv[i]\n+                else:\n+                    raise needs_value(spelling, spec)\n+            else:\n+                if rest:\n+                    if rest not in spec.choices:\n+                        raise CliError(f\"Flag {spelling} cannot take a value\")\n+                    value = rest\n+                elif i + 1 < len(argv) and argv[i + 1] in spec.choices:\n+                    i += 1\n+                    value = argv[i]\n+                else:\n+                    value = spec.default\n+            occurrences.append(Occurrence(spec.canonical, value, position, spelling))\n+            position += 1\n+            break\n+        i += 1\n+\n+    return occurrences, paths\n+\n+\n+@dataclass\n+class Config:\n+    occurrences: list[Occurrence]\n+    paths: list[str]\n+    mode: str = \"lines\"\n+    table: bool = False\n+    tree: bool = False\n+    width: Optional[int] = None\n+    across: bool = False\n+    recurse: bool = False\n+    level: Optional[int] = None\n+    all_count: int = 0\n+    show_hidden: bool = False\n+    show_dots: bool = False\n+    sort_field: str = \"name\"\n+    sort_upper_first: bool = False\n+    reverse: bool = False\n+    dirs_first: bool = False\n+    dirs_last: bool = False\n+    only_dirs: bool = False\n+    only_files: bool = False\n+    no_symlinks: bool = False\n+    show_symlinks: bool = False\n+    ignore_patterns: list[str] = field(default_factory=list)\n+    treat_dirs: bool = False\n+    follow_symlinks: bool = False\n+    dereference: bool = False\n+    classify: str = \"never\"\n+    no_quotes: bool = False\n+    absolute: str = \"off\"\n+    header: bool = False\n+    permissions: bool = True\n+    filesize: bool = True\n+    file_flags: bool = False\n+    size_format: str = \"decimal\"\n+    time_fields: list[str] = field(default_factory=lambda: [\"modified\"])\n+    time_style: str = \"default\"\n+\n+    def has(self, name: str) -> bool:\n+        return any(o.canonical == name for o in self.occurrences)\n+\n+    def count(self, name: str) -> int:\n+        return sum(o.canonical == name for o in self.occurrences)\n+\n+    def last(self, *names: str) -> Optional[Occurrence]:\n+        choices = [o for o in self.occurrences if o.canonical in names]\n+        return max(choices, key=lambda o: o.position) if choices else None\n+\n+\n+def parse_nonnegative(value: str, source: str) -> int:\n+    if not value or not value.isascii() or not value.isdigit():\n+        raise CliError(\n+            f'Value \"{value}\" not valid for option {option_label(source)}: '\n+            \"invalid digit found in string\"\n+        )\n+    return int(value)\n+\n+\n+def make_config(occurrences: list[Occurrence], paths: list[str]) -> Config:\n+    cfg = Config(occurrences, paths)\n+\n+    width_occ = cfg.last(\"width\")\n+    if width_occ is not None:\n+        cfg.width = parse_nonnegative(width_occ.value or \"\", \"width\")\n+    elif os.environ.get(\"COLUMNS\"):\n+        value = os.environ[\"COLUMNS\"]\n+        if not value.isdigit():\n+            raise CliError(\n+                f'Value \"{value}\" not valid for environment variable COLUMNS: '\n+                \"invalid digit found in string\"\n+            )\n+        cfg.width = int(value)\n+    elif sys.stdout.isatty():\n+        cfg.width = shutil.get_terminal_size((80, 24)).columns\n+\n+    display = cfg.last(\"long\", \"oneline\", \"grid\", \"tree\")\n+    has_long = cfg.has(\"long\")\n+    if display is None:\n+        cfg.mode = \"grid\" if cfg.width is not None else \"lines\"\n+    elif display.canonical == \"long\" or (\n+        display.canonical in (\"tree\", \"grid\") and has_long\n+    ):\n+        last_structure = cfg.last(\"grid\", \"tree\")\n+        cfg.mode = (\n+            \"grid-details\"\n+            if last_structure is not None and last_structure.canonical == \"grid\"\n+            else \"details\"\n+        )\n+    elif display.canonical == \"tree\":\n+        cfg.mode = \"details\"\n+        cfg.tree = True\n+    elif display.canonical == \"oneline\":\n+        cfg.mode = \"lines\"\n+    else:\n+        cfg.mode = \"grid\"\n+\n+    if cfg.has(\"tree\") and cfg.mode == \"details\":\n+        last_structure = cfg.last(\"tree\", \"grid\")\n+        cfg.tree = last_structure is not None and last_structure.canonical == \"tree\"\n+    cfg.table = has_long and cfg.mode in (\"details\", \"grid-details\")\n+    cfg.across = cfg.has(\"across\")\n+    cfg.recurse = cfg.has(\"recurse\") or cfg.tree\n+\n+    level_occ = cfg.last(\"level\")\n+    if level_occ is not None and cfg.recurse:\n+        cfg.level = parse_nonnegative(level_occ.value or \"\", \"level\")\n+        if cfg.level == 0:\n+            cfg.level = None\n+\n+    cfg.all_count = cfg.count(\"all\")\n+    cfg.show_hidden = cfg.all_count > 0 or cfg.has(\"almost-all\")\n+    cfg.show_dots = cfg.all_count >= 2\n+    if cfg.has(\"tree\") and cfg.show_dots:\n+        raise CliError(\"Option --tree is useless given --all --all\")\n+\n+    sort_occ = cfg.last(\"sort\")\n+    sort_value = sort_occ.value if sort_occ else \"name\"\n+    if sort_value == \"inode\" and os.name == \"nt\":\n+        sort_spec = None\n+    else:\n+        sort_spec = SORT_ALIASES.get(sort_value or \"\")\n+    if sort_spec is None:\n+        choices = \", \".join(SORT_CHOICES)\n+        raise CliError(\n+            f'Option --sort (-s) has no \"{sort_value}\" setting (choices: {choices})'\n+        )\n+    cfg.sort_field, cfg.sort_upper_first = sort_spec\n+\n+    cfg.reverse = cfg.has(\"reverse\")\n+    cfg.dirs_first = cfg.has(\"dirs-first\")\n+    cfg.dirs_last = cfg.has(\"dirs-last\")\n+    cfg.only_dirs = cfg.has(\"only-dirs\")\n+    cfg.only_files = cfg.has(\"only-files\")\n+    cfg.no_symlinks = cfg.has(\"no-symlinks\")\n+    cfg.show_symlinks = cfg.has(\"show-symlinks\")\n+    cfg.treat_dirs = cfg.has(\"treat-dirs-as-files\") or cfg.has(\"list-dirs\")\n+    cfg.follow_symlinks = cfg.has(\"follow-symlinks\")\n+    cfg.dereference = cfg.has(\"dereference\")\n+\n+    for occurrence in occurrences:\n+        if occurrence.canonical == \"ignore-glob\" and occurrence.value is not None:\n+            cfg.ignore_patterns.extend(occurrence.value.split(\"|\"))\n+\n+    classify = cfg.last(\"classify\")\n+    if classify:\n+        value = classify.value or \"auto\"\n+        if value not in (\"always\", \"auto\", \"automatic\", \"never\"):\n+            raise CliError(f'Option --classify (-F) has no \"{value}\" setting')\n+        cfg.classify = \"always\" if value == \"always\" else \"never\"\n+\n+    absolute = cfg.last(\"absolute\")\n+    if absolute:\n+        value = absolute.value or \"on\"\n+        if value not in (\"on\", \"yes\", \"follow\", \"off\", \"no\"):\n+            raise CliError(f'Option --absolute has no \"{value}\" setting')\n+        cfg.absolute = \"off\" if value in (\"off\", \"no\") else value\n+\n+    cfg.no_quotes = cfg.has(\"no-quotes\")\n+    cfg.header = cfg.has(\"header\") and cfg.table\n+    cfg.permissions = not cfg.has(\"no-permissions\")\n+    cfg.filesize = not cfg.has(\"no-filesize\")\n+    cfg.file_flags = cfg.has(\"flags\")\n+\n+    size_occ = cfg.last(\"binary\", \"bytes\")\n+    if size_occ and size_occ.canonical == \"binary\":\n+        cfg.size_format = \"binary\"\n+    elif size_occ and size_occ.canonical == \"bytes\":\n+        cfg.size_format = \"bytes\"\n+\n+    explicit_times: list[str] = []\n+    time_value = cfg.last(\"time\")\n+    if time_value:\n+        if time_value.value not in (\"modified\", \"changed\", \"accessed\", \"created\"):\n+            choices = \"modified, changed, accessed, created\"\n+            raise CliError(\n+                f'Option --time (-t) has no \"{time_value.value}\" setting '\n+                f\"(choices: {choices})\"\n+            )\n+        explicit_times.append(time_value.value or \"modified\")\n+    for name in (\"modified\", \"changed\", \"created\", \"accessed\"):\n+        if cfg.has(name) and name not in explicit_times:\n+            explicit_times.append(name)\n+    if explicit_times:\n+        cfg.time_fields = [\n+            name\n+            for name in (\"modified\", \"changed\", \"created\", \"accessed\")\n+            if name in explicit_times\n+        ]\n+    if cfg.has(\"no-time\"):\n+        cfg.time_fields = []\n+\n+    style_occ = cfg.last(\"time-style\")\n+    if style_occ and cfg.table:\n+        value = style_occ.value or \"\"\n+        if value not in (\"default\", \"iso\", \"long-iso\", \"full-iso\", \"relative\") and not value.startswith(\"+\"):\n+            choices = \"default, long-iso, full-iso, iso, relative\"\n+            raise CliError(\n+                f'Option --time-style has no \"{value}\" setting (choices: {choices})'\n+            )\n+        cfg.time_style = value\n+    elif cfg.table and os.environ.get(\"TIME_STYLE\"):\n+        cfg.time_style = os.environ[\"TIME_STYLE\"]\n+\n+    return cfg\n+\n+\n+_MISSING = object()\n+\n+\n+@dataclass\n+class Entry:\n+    path: str\n+    name: str\n+    parent_dir: Optional[str] = None\n+    synthetic: bool = False\n+    dereference: bool = False\n+    _lstat_value: object = field(default=_MISSING, repr=False)\n+    _stat_value: object = field(default=_MISSING, repr=False)\n+\n+    def lstat(self):\n+        if self._lstat_value is _MISSING:\n+            self._lstat_value = os.lstat(self.path)\n+        return self._lstat_value\n+\n+    def metadata(self):\n+        if not self.dereference:\n+            return self.lstat()\n+        if self._stat_value is _MISSING:\n+            self._stat_value = os.stat(self.path)\n+        return self._stat_value\n+\n+    def is_link(self) -> bool:\n+        try:\n+            return os.path.islink(self.path) or stat.S_ISLNK(self.lstat().st_mode)\n+        except OSError:\n+            return False\n+\n+    def is_directory(self) -> bool:\n+        if self.is_link() and not self.dereference:\n+            return False\n+        try:\n+            return stat.S_ISDIR(self.metadata().st_mode)\n+        except OSError:\n+            return False\n+\n+    def points_to_directory(self) -> bool:\n+        try:\n+            return os.path.isdir(self.path)\n+        except OSError:\n+            return False\n+\n+    def is_file(self) -> bool:\n+        if self.is_link() and not self.dereference:\n+            return False\n+        try:\n+            return stat.S_ISREG(self.metadata().st_mode)\n+        except OSError:\n+            return False\n+\n+    def attributes(self) -> int:\n+        try:\n+            return int(getattr(self.metadata(), \"st_file_attributes\", 0))\n+        except OSError:\n+            return 0\n+\n+    def size(self) -> Optional[int]:\n+        if self.is_directory():\n+            return None\n+        try:\n+            return int(self.metadata().st_size)\n+        except OSError:\n+            return 0\n+\n+    def time_ns(self, kind: str) -> Optional[int]:\n+        try:\n+            metadata = self.metadata()\n+        except OSError:\n+            return None\n+        if kind == \"modified\":\n+            return int(metadata.st_mtime_ns)\n+        if kind == \"accessed\":\n+            return int(metadata.st_atime_ns)\n+        if kind == \"created\":\n+            return int(metadata.st_ctime_ns)\n+        return None\n+\n+    def type_rank(self) -> int:\n+        if self.is_directory():\n+            return 0\n+        if self.is_file():\n+            return 1\n+        if self.is_link():\n+            return 2\n+        return 7\n+\n+\n+def path_name(path: str) -> str:\n+    trimmed = path.rstrip(\"/\\\\\")\n+    if not trimmed:\n+        return path\n+    name = os.path.basename(trimmed)\n+    return name if name else trimmed\n+\n+\n+def make_entry(path: str, parent_dir: Optional[str] = None, name: Optional[str] = None, *, cfg: Config) -> Entry:\n+    return Entry(\n+        path=path,\n+        name=path_name(path) if name is None else name,\n+        parent_dir=parent_dir,\n+        dereference=cfg.dereference,\n+    )\n+\n+\n+def display_width(text: str) -> int:\n+    width = 0\n+    for char in text:\n+        if unicodedata.combining(char):\n+            continue\n+        width += 2 if unicodedata.east_asian_width(char) in (\"W\", \"F\") else 1\n+    return width\n+\n+\n+def escaped(text: str) -> str:\n+    replacements = {\n+        \"\\n\": r\"\\n\",\n+        \"\\r\": r\"\\r\",\n+        \"\\t\": r\"\\t\",\n+        \"\\x1b\": r\"\\e\",\n+    }\n+    bits = []\n+    for char in text:\n+        if char in replacements:\n+            bits.append(replacements[char])\n+        elif ord(char) < 32 or ord(char) == 127:\n+            bits.append(f\"\\\\x{ord(char):02x}\")\n+        else:\n+            bits.append(char)\n+    return \"\".join(bits)\n+\n+\n+def quote(text: str, no_quotes: bool = False) -> str:\n+    text = escaped(text)\n+    if no_quotes or not any(char.isspace() for char in text):\n+        return text\n+    return \"'\" + text.replace(\"'\", \"\\\\'\") + \"'\"\n+\n+\n+def explicit_display_path(entry: Entry, cfg: Config) -> str:\n+    if cfg.absolute != \"off\":\n+        result = os.path.realpath(entry.path) if cfg.absolute == \"follow\" else os.path.abspath(entry.path)\n+        return quote(result, cfg.no_quotes)\n+    if entry.parent_dir is not None:\n+        return quote(entry.name, cfg.no_quotes)\n+    parent = os.path.dirname(entry.path)\n+    if not parent:\n+        return quote(entry.name, cfg.no_quotes)\n+    return quote(parent, cfg.no_quotes) + os.sep + quote(entry.name, cfg.no_quotes)\n+\n+\n+def link_target(entry: Entry) -> Optional[str]:\n+    if not entry.is_link():\n+        return None\n+    try:\n+        return os.readlink(entry.path)\n+    except OSError:\n+        return None\n+\n+\n+def render_name(entry: Entry, cfg: Config, *, show_link: bool) -> str:\n+    name = explicit_display_path(entry, cfg)\n+    target = link_target(entry) if show_link else None\n+    if target is not None:\n+        target_text = quote(target, False)\n+        if cfg.classify == \"always\":\n+            target_path = target if os.path.isabs(target) else os.path.join(os.path.dirname(entry.path), target)\n+            if os.path.isdir(target_path):\n+                target_text += \"/\"\n+        return f\"{name} -> {target_text}\"\n+    if cfg.classify == \"always\":\n+        if entry.is_directory():\n+            name += \"/\"\n+        elif entry.is_link():\n+            name += \"@\"\n+    return name\n+\n+\n+def natural_key(text: str, upper_first: bool = False):\n+    parts = re.split(r\"(\\d+)\", text)\n+    key = []\n+    for part in parts:\n+        if part.isdigit():\n+            key.append((0, int(part), len(part)))\n+        else:\n+            key.append((1, part if upper_first else part.casefold()))\n+    return tuple(key)\n+\n+\n+def extension_of(name: str) -> Optional[str]:\n+    position = name.rfind(\".\")\n+    return None if position < 0 else name[position + 1 :].lower()\n+\n+\n+def entry_sort_key(entry: Entry, cfg: Config):\n+    field_name = cfg.sort_field\n+    if field_name == \"none\":\n+        return 0\n+    if field_name in (\"name\", \"hidden-name\"):\n+        name = entry.name\n+        if field_name == \"hidden-name\" and name.startswith(\".\"):\n+            name = name[1:]\n+        return natural_key(name, cfg.sort_upper_first)\n+    if field_name == \"extension\":\n+        extension = extension_of(entry.name)\n+        if extension is None:\n+            return (0, (), natural_key(entry.name, cfg.sort_upper_first))\n+        return (\n+            1,\n+            natural_key(extension, cfg.sort_upper_first),\n+            natural_key(entry.name, cfg.sort_upper_first),\n+        )\n+    if field_name == \"size\":\n+        size = entry.size()\n+        return (-1 if size is None else size)\n+    if field_name == \"type\":\n+        return (entry.type_rank(), natural_key(entry.name, False))\n+    if field_name == \"age\":\n+        return -(entry.time_ns(\"modified\") or 0)\n+    if field_name in (\"modified\", \"accessed\", \"created\", \"changed\"):\n+        return entry.time_ns(field_name) or 0\n+    return natural_key(entry.name, False)\n+\n+\n+def sort_entries(entries: list[Entry], cfg: Config) -> list[Entry]:\n+    if cfg.sort_field != \"none\":\n+        entries = sorted(entries, key=lambda item: entry_sort_key(item, cfg))\n+    if cfg.reverse:\n+        entries.reverse()\n+    if cfg.dirs_first:\n+        entries = sorted(entries, key=lambda item: not item.points_to_directory())\n+    elif cfg.dirs_last:\n+        entries = sorted(entries, key=lambda item: item.points_to_directory())\n+    return entries\n+\n+\n+def ignored(name: str, cfg: Config) -> bool:\n+    return any(fnmatch.fnmatchcase(name, pattern) for pattern in cfg.ignore_patterns)\n+\n+\n+def hidden_entry(entry: Entry) -> bool:\n+    if entry.name.startswith((\".\", \"_\")):\n+        return True\n+    return bool(entry.attributes() & FILE_ATTRIBUTE_HIDDEN)\n+\n+\n+def child_passes(entry: Entry, cfg: Config, *, recursing: bool) -> bool:\n+    if ignored(entry.name, cfg):\n+        return False\n+    only_dirs = cfg.only_dirs\n+    only_files = cfg.only_files\n+    no_links = cfg.no_symlinks\n+    show_links = cfg.show_symlinks\n+    if only_dirs and not only_files:\n+        if show_links:\n+            return entry.is_directory() or entry.points_to_directory()\n+        return entry.is_directory()\n+    if only_files and not only_dirs:\n+        if recursing:\n+            return True\n+        if show_links:\n+            return entry.is_file() or (entry.is_link() and not entry.points_to_directory())\n+        return entry.is_file()\n+    if no_links and not show_links:\n+        return not entry.is_link()\n+    return True\n+\n+\n+def scan_directory(path: str, cfg: Config, *, recursing: bool) -> tuple[list[Entry], Optional[OSError]]:\n+    entries: list[Entry] = []\n+    if cfg.show_dots:\n+        entries.append(Entry(path, \".\", path, True, cfg.dereference))\n+        entries.append(Entry(os.path.join(path, \"..\"), \"..\", path, True, cfg.dereference))\n+    try:\n+        with os.scandir(path) as iterator:\n+            for item in iterator:\n+                entry = make_entry(item.path, path, item.name, cfg=cfg)\n+                if not cfg.show_hidden and hidden_entry(entry):\n+                    continue\n+                if child_passes(entry, cfg, recursing=recursing):\n+                    entries.append(entry)\n+    except OSError as error:\n+        return [], error\n+    return sort_entries(entries, cfg), None\n+\n+\n+def grid_lines(cells: Sequence[str], width: int, across: bool, gap: int = 2) -> list[str]:\n+    if not cells:\n+        return []\n+    count = len(cells)\n+    chosen_rows = count\n+    chosen_cols = 1\n+    chosen_widths = [max(display_width(cell) for cell in cells)]\n+\n+    for rows in range(1, count + 1):\n+        cols = math.ceil(count / rows)\n+        widths = [0] * cols\n+        for index, cell in enumerate(cells):\n+            if across:\n+                col = index % cols\n+            else:\n+                col = index // rows\n+            widths[col] = max(widths[col], display_width(cell))\n+        total = sum(widths) + gap * (cols - 1)\n+        if total <= width or cols == 1:\n+            chosen_rows, chosen_cols, chosen_widths = rows, cols, widths\n+            break\n+\n+    output: list[str] = []\n+    for row in range(chosen_rows):\n+        row_cells: list[tuple[int, str]] = []\n+        for col in range(chosen_cols):\n+            index = row * chosen_cols + col if across else col * chosen_rows + row\n+            if index < count:\n+                row_cells.append((col, cells[index]))\n+        if not row_cells:\n+            continue\n+        bits: list[str] = []\n+        for cell_index, (col, cell) in enumerate(row_cells):\n+            bits.append(cell)\n+            if cell_index < len(row_cells) - 1:\n+                padding = chosen_widths[col] - display_width(cell) + gap\n+                bits.append(\" \" * padding)\n+        output.append(\"\".join(bits))\n+    return output\n+\n+\n+def windows_mode(entry: Entry) -> str:\n+    attrs = entry.attributes()\n+    if entry.is_link():\n+        kind = \"l\"\n+    elif entry.is_directory():\n+        kind = \"d\"\n+    else:\n+        kind = \"-\"\n+    return \"\".join(\n+        (\n+            kind,\n+            \"a\" if attrs & FILE_ATTRIBUTE_ARCHIVE else \"-\",\n+            \"r\" if attrs & FILE_ATTRIBUTE_READONLY else \"-\",\n+            \"h\" if attrs & FILE_ATTRIBUTE_HIDDEN else \"-\",\n+            \"s\" if attrs & FILE_ATTRIBUTE_SYSTEM else \"-\",\n+        )\n+    )\n+\n+\n+def file_flags(entry: Entry) -> str:\n+    attrs = entry.attributes()\n+    ordered = (\n+        (FILE_ATTRIBUTE_READONLY, \"readonly\"),\n+        (FILE_ATTRIBUTE_HIDDEN, \"hidden\"),\n+        (FILE_ATTRIBUTE_SYSTEM, \"system\"),\n+        (FILE_ATTRIBUTE_ARCHIVE, \"archive\"),\n+        (FILE_ATTRIBUTE_TEMPORARY, \"temporary\"),\n+        (FILE_ATTRIBUTE_COMPRESSED, \"compressed\"),\n+        (FILE_ATTRIBUTE_OFFLINE, \"offline\"),\n+        (FILE_ATTRIBUTE_NOT_CONTENT_INDEXED, \"not indexed\"),\n+        (FILE_ATTRIBUTE_ENCRYPTED, \"encrypted\"),\n+        (FILE_ATTRIBUTE_NO_SCRUB_DATA, \"no scrub\"),\n+        (FILE_ATTRIBUTE_UNPINNED, \"unpinned\"),\n+        (FILE_ATTRIBUTE_PINNED, \"pinned\"),\n+        (FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS, \"recall on data access\"),\n+    )\n+    names = [name for flag_value, name in ordered if attrs & flag_value]\n+    return \"-\" if not names else \"-\".join(names)\n+\n+\n+def formatted_size(entry: Entry, mode: str) -> str:\n+    size = entry.size()\n+    if size is None:\n+        return \"-\"\n+    if mode == \"bytes\":\n+        return f\"{size:,}\"\n+    base = 1024 if mode == \"binary\" else 1000\n+    symbols = (\"\", \"Ki\", \"Mi\", \"Gi\", \"Ti\", \"Pi\", \"Ei\") if mode == \"binary\" else (\"\", \"k\", \"M\", \"G\", \"T\", \"P\", \"E\")\n+    if size < base:\n+        return f\"{size:,}\"\n+    exponent = min(int(math.log(size, base)), len(symbols) - 1)\n+    number = size / (base**exponent)\n+    rendered = f\"{number:.1f}\" if number < 10 else f\"{math.floor(number + 0.5):,}\"\n+    return rendered + symbols[exponent]\n+\n+\n+def fixed_local_datetime(timestamp_ns: int) -> tuple[dt.datetime, dt.timedelta]:\n+    timestamp = timestamp_ns / 1_000_000_000\n+    utc = dt.datetime.fromtimestamp(timestamp, dt.timezone.utc).replace(tzinfo=None)\n+    offset = dt.datetime.now().astimezone().utcoffset() or dt.timedelta(0)\n+    return utc + offset, offset\n+\n+\n+def relative_time(value: dt.datetime) -> str:\n+    now = dt.datetime.now()\n+    seconds = max(0, int((now - value).total_seconds()))\n+    ranges = (\n+        (365 * 86400, \"year\"),\n+        (30 * 86400, \"month\"),\n+        (7 * 86400, \"week\"),\n+        (86400, \"day\"),\n+        (3600, \"hour\"),\n+        (60, \"minute\"),\n+    )\n+    for divisor, label in ranges:\n+        if seconds >= divisor:\n+            amount = max(1, math.floor(seconds / divisor + 0.5))\n+            return f\"{amount} {label}{'' if amount == 1 else 's'}\"\n+    return \"now\"\n+\n+\n+def chrono_custom(value: dt.datetime, pattern: str) -> str:\n+    pattern = pattern.replace(\"%_d\", \"{EZA_DAY}\").replace(\"%f\", \"{EZA_NANO}\")\n+    output = value.strftime(pattern)\n+    output = output.replace(\"{EZA_DAY}\", f\"{value.day:2d}\")\n+    output = output.replace(\"{EZA_NANO}\", f\"{value.microsecond * 1000:09d}\")\n+    return output\n+\n+\n+def formatted_time(entry: Entry, kind: str, style: str) -> str:\n+    timestamp_ns = entry.time_ns(kind)\n+    if timestamp_ns is None:\n+        return \"-\"\n+    value, offset = fixed_local_datetime(timestamp_ns)\n+    current_year = dt.datetime.now().year\n+    if style == \"default\":\n+        if value.year == current_year:\n+            return f\"{value.day:2d} {value.strftime('%b')} {value:%H:%M}\"\n+        return f\"{value.day:2d} {value.strftime('%b')}  {value:%Y}\"\n+    if style == \"iso\":\n+        return value.strftime(\"%m-%d %H:%M\" if value.year == current_year else \"%Y-%m-%d\")\n+    if style == \"long-iso\":\n+        return value.strftime(\"%Y-%m-%d %H:%M\")\n+    if style == \"full-iso\":\n+        total_minutes = int(offset.total_seconds() // 60)\n+        sign = \"+\" if total_minutes >= 0 else \"-\"\n+        total_minutes = abs(total_minutes)\n+        zone = f\"{sign}{total_minutes // 60:02d}{total_minutes % 60:02d}\"\n+        nanos = timestamp_ns % 1_000_000_000\n+        return value.strftime(\"%Y-%m-%d %H:%M:%S\") + f\".{nanos:09d} {zone}\"\n+    if style == \"relative\":\n+        return relative_time(value)\n+    if style.startswith(\"+\"):\n+        formats = style[1:].split(\"\\n\")\n+        pattern = formats[1] if len(formats) > 1 and value.year == current_year else formats[0]\n+        return chrono_custom(value, pattern)\n+    return formatted_time(entry, kind, \"default\")\n+\n+\n+@dataclass(frozen=True)\n+class Column:\n+    key: str\n+    header: str\n+    alignment: str\n+\n+\n+def columns_for(cfg: Config) -> list[Column]:\n+    columns: list[Column] = []\n+    if cfg.permissions:\n+        columns.append(Column(\"mode\", \"Mode\", \"left\"))\n+    if cfg.filesize:\n+        columns.append(Column(\"size\", \"Size\", \"right\"))\n+    if cfg.file_flags:\n+        columns.append(Column(\"flags\", \"Flags\", \"left\"))\n+    for kind in cfg.time_fields:\n+        columns.append(Column(f\"time:{kind}\", f\"Date {kind.capitalize()}\", \"right\"))\n+    return columns\n+\n+\n+def column_value(entry: Entry, column: Column, cfg: Config) -> str:\n+    if column.key == \"mode\":\n+        return windows_mode(entry)\n+    if column.key == \"size\":\n+        return formatted_size(entry, cfg.size_format)\n+    if column.key == \"flags\":\n+        return file_flags(entry)\n+    if column.key.startswith(\"time:\"):\n+        return formatted_time(entry, column.key.split(\":\", 1)[1], cfg.time_style)\n+    return \"-\"\n+\n+\n+@dataclass(frozen=True)\n+class TreeRow:\n+    entry: Entry\n+    prefix: str\n+\n+\n+def prepare_table(rows: Sequence[TreeRow], cfg: Config):\n+    columns = columns_for(cfg)\n+    values = [[column_value(row.entry, column, cfg) for column in columns] for row in rows]\n+    widths = [0] * len(columns)\n+    for index, column in enumerate(columns):\n+        if cfg.header:\n+            widths[index] = display_width(column.header)\n+        for row_values in values:\n+            widths[index] = max(widths[index], display_width(row_values[index]))\n+    return columns, values, widths\n+\n+\n+def render_metadata(values: Sequence[str], columns: Sequence[Column], widths: Sequence[int]) -> str:\n+    bits: list[str] = []\n+    for value, column, width in zip(values, columns, widths):\n+        padding = width - display_width(value)\n+        if column.alignment == \"right\":\n+            bits.append(\" \" * padding + value)\n+        else:\n+            bits.append(value + \" \" * padding)\n+        bits.append(\" \")\n+    return \"\".join(bits)\n+\n+\n+def render_details(rows: Sequence[TreeRow], cfg: Config) -> list[str]:\n+    columns, values, widths = prepare_table(rows, cfg)\n+    output: list[str] = []\n+    if cfg.header:\n+        header_values = [column.header for column in columns]\n+        output.append(render_metadata(header_values, columns, widths) + \"Name\")\n+    for row, row_values in zip(rows, values):\n+        metadata = render_metadata(row_values, columns, widths)\n+        output.append(metadata + row.prefix + render_name(row.entry, cfg, show_link=True))\n+    return output\n+\n+\n+def render_entries(entries: list[Entry], cfg: Config, parent: Optional[str] = None) -> list[str]:\n+    entries = sort_entries(entries, cfg)\n+    if cfg.mode == \"lines\":\n+        return [render_name(entry, cfg, show_link=True) for entry in entries]\n+    if cfg.mode == \"grid\":\n+        width = cfg.width if cfg.width is not None else 80\n+        cells = [render_name(entry, cfg, show_link=False) for entry in entries]\n+        return grid_lines(cells, width, cfg.across)\n+    rows = [TreeRow(entry, \"\") for entry in entries]\n+    if cfg.mode == \"grid-details\" and cfg.width is not None:\n+        columns, values, widths = prepare_table(rows, cfg)\n+        cells = []\n+        for row, row_values in zip(rows, values):\n+            details = render_metadata(row_values, columns, widths)\n+            cells.append(details + \" \" + render_name(row.entry, cfg, show_link=False))\n+        threshold = os.environ.get(\"EZA_GRID_ROWS\") or os.environ.get(\"EXA_GRID_ROWS\")\n+        lines = grid_lines(cells, cfg.width, False, 4)\n+        if threshold and threshold.isdigit() and len(lines) < int(threshold):\n+            return render_details(rows, cfg)\n+        if cfg.header and columns:\n+            combined = render_metadata([column.header for column in columns], columns, widths) + \"Name\"\n+            return [combined] + lines\n+        return lines\n+    return render_details(rows, cfg)\n+\n+\n+def tree_prefix(ancestors_last: Sequence[bool], last: bool) -> str:\n+    return \"\".join(\"    \" if item else \"|   \" for item in ancestors_last) + (\"`-- \" if last else \"|-- \")\n+\n+\n+def unicode_tree_prefix(ancestors_last: Sequence[bool], last: bool) -> str:\n+    return \"\".join(\"    \" if item else \"│   \" for item in ancestors_last) + (\"└── \" if last else \"├── \")\n+\n+\n+def flatten_tree(\n+    entry: Entry,\n+    cfg: Config,\n+    rows: list[TreeRow],\n+    depth: int,\n+    ancestors_last: tuple[bool, ...],\n+    last: bool,\n+    visited: set[str],\n+) -> None:\n+    prefix = \"\" if depth == 0 else unicode_tree_prefix(ancestors_last, last)\n+    rows.append(TreeRow(entry, prefix))\n+    if cfg.level is not None and depth >= cfg.level:\n+        return\n+    can_descend = entry.is_directory() or (\n+        cfg.follow_symlinks and entry.is_link() and entry.points_to_directory()\n+    )\n+    if not can_descend or entry.synthetic:\n+        return\n+    try:\n+        identity = os.path.realpath(entry.path).casefold()\n+    except OSError:\n+        identity = os.path.abspath(entry.path).casefold()\n+    if identity in visited:\n+        return\n+    vi